import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-a2-001","clusterId":"A","werkstueckRef":"A.12","stufe":1,"question":"Maja sagt: „Stell dir mal vor, die Geheimdienste hätten alles von langer Hand geplant, und dann passiert genau das, was man jetzt in den Nachrichten sieht. Passt doch alles zusammen, also muss es so gewesen sein.“ Woran erkennst du, dass das keine tragfähige Überlegung ist?","options":["Sie legt weder Annahmen noch Spielregeln fest und kreist um eine bereits feststehende Überzeugung, statt prüfbare Folgen herzuleiten.","Sie arbeitet mit einem erfundenen Szenario, und erfundene Szenarien taugen grundsätzlich nicht zum Nachdenken über die Wirklichkeit.","Sie bleibt zu vage, weil sie keine Messwerte nennt, und erst mit Messwerten wird aus einer Überlegung ein Gedankenexperiment.","Sie ist zu einfach, weil echte Gedankenexperimente immer mehrere Szenarien gleichzeitig durchspielen und gegeneinander abwägen."],"correctIndex":0,"explanation":"Ein Gedankenexperiment legt die Annahme und die Spielregeln vorab fest und folgt dann konsequent der Logik, um Stimmigkeit und Folgen zu prüfen. Majas Überlegung tut das Gegenteil: Sie beginnt beim gewünschten Ergebnis und schmückt es aus. Dass „alles zusammenpasst“, ist bei einer frei erzählten Geschichte kein Wunder, denn sie lässt sich beliebig anpassen. Erfundene Szenarien sind dagegen nicht das Problem, auch Einstein stellte sich vor, einem Lichtstrahl hinterherzujagen. Entscheidend ist, ob Regeln gelten und ob sich daraus Schlüsse ziehen lassen, die man nachprüfen kann. Und selbst ein sauber durchgeführtes Gedankenexperiment liefert keinen Befund über die Wirklichkeit, sondern prüft nur, ob eine Idee in sich stimmig ist.","coreRule":"⚡ Ein Gedankenexperiment braucht klare Anfangsbedingungen und Regeln und leitet prüfbare Folgen her. Eine Geschichte, die nur eine fertige Überzeugung ausschmückt, ist kein Test.","quote":"","quoteLabel":"","beleg":"Werkstück A.12 (Kontext & Tiefe; Red Flag „Unstrukturierte Fantasie“; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Maja beginnt bei dem Ergebnis, das sie für wahr hält, und schmückt es aus, statt Annahmen und Regeln festzulegen und daraus prüfbare Folgen abzuleiten. Dass „alles zusammenpasst“, ist bei einer frei erzählten Geschichte kein Wunder, denn sie lässt sich beliebig anpassen.","prueffrage":"Hätte Maja dieselbe Geschichte auch erzählen können, wenn in den Nachrichten etwas ganz anderes passiert wäre?","rueckmeldung":[{"option":1,"text":"Dass Majas Szenario erfunden ist, wirkt wie der Haken, ist es aber nicht: Auch Einstein stellte sich vor, einem Lichtstrahl hinterherzujagen. Es kommt darauf an, ob feste Regeln gelten und sich daraus nachprüfbare Schlüsse ziehen lassen."},{"option":2,"text":"Ein Mangel an Zahlen fällt leicht auf, ist hier aber nicht der Kern. Ein Gedankenexperiment braucht keine Messwerte, sondern vorab festgelegte Annahmen und Spielregeln. Genau die fehlen bei Maja."},{"option":3,"text":"Mehrere Szenarien gegeneinander abzuwägen kann nützlich sein, ist aber keine Bedingung. Auch ein einzelnes Gedankenexperiment kann tragen, wenn es klare Annahmen und Regeln hat und prüfbare Folgen liefert. Bei Maja fehlt beides."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-a2-002","clusterId":"A","werkstueckRef":"A.12","stufe":2,"question":"Welcher Prüfschritt deckt am besten auf, ob diese Behauptung in sich stimmig ist?","scenario":"Eine Bekannte erklärt dir beim Kaffee: „Deine Gedanken erschaffen deine Realität. Wer fest genug an etwas denkt, bekommt es auch.“ Du willst die Behauptung prüfen, ohne gleich ein aufwendiges Experiment zu planen.","options":["Du nimmst an, sie gelte für alle Menschen gleichzeitig, und suchst nach Widersprüchen, etwa wenn zwei Menschen sich denselben einmaligen Lottogewinn vorstellen.","Du sammelst Fälle, in denen intensives Vorstellen geholfen hat, und stellst sie den gescheiterten Versuchen aus deinem Umfeld gegenüber.","Du erklärst die Behauptung für gegenstandslos, weil sich Gedanken mit keinem Messgerät erfassen lassen und sie deshalb nicht untersuchbar ist.","Du fragst, wer die Idee zuerst vertreten hat, und bewertest sie nach Ausbildung, Ruf und Auftreten dieser Person."],"correctIndex":0,"explanation":"Ein Gedankenexperiment macht eine Behauptung testbar, ohne dass man sie in der Wirklichkeit ausprobieren muss: Man setzt sie als wahr voraus und spielt durch, was daraus folgt. Gilt der Satz für alle 8 Milliarden Menschen, müsste derselbe einmalige Lottogewinn mehreren Menschen zufallen. Ein Diktator, der sich den Gehorsam aller wünscht, und ein Freiheitskämpfer, der sich die Freiheit aller wünscht, würden unvereinbare Realitäten erzeugen. Eine Behauptung, die im Maßstab in Widersprüche gerät, ist in sich nicht stimmig. Eine Fallsammlung dagegen zählt nur die Treffer und zeigt nichts über die innere Logik. Dass Gedanken nicht messbar sind, macht die Behauptung nicht gegenstandslos, denn ihre Folgen lassen sich durchdenken. Und wer eine Idee geäußert hat, sagt nichts darüber, ob sie stimmt.","coreRule":"⚡ Prüfe eine Behauptung, indem du sie als wahr annimmst und im großen Maßstab durchspielst: Bleibt sie widerspruchsfrei?","beleg":"Werkstück A.12 (Anwendung: Esoterik & New Age, „Gesetz der Anziehung“)","status":"entwurf","kurz":"Setze den Satz als wahr voraus und spiele die Folgen durch: Wünschen zwei Menschen sich denselben einmaligen Lottogewinn, kann er nicht beiden zufallen. Ein Satz, der im großen Maßstab an solchen Widersprüchen scheitert, ist in sich nicht stimmig.","prueffrage":"Erfährst du aus gezählten Erfolgen oder aus dem Ruf einer Person, ob der Satz sich selbst widerspricht?","rueckmeldung":[{"option":1,"text":"Erfahrungsfälle zu vergleichen ist an sich vernünftig. Sie zeigen aber nur, wie oft etwas eintrat, und sagen nichts darüber, ob der Satz in sich stimmig ist, also ob seine Folgen zusammenpassen."},{"option":2,"text":"Dass sich Gedanken kaum direkt messen lassen, wirkt wie ein Grund, die Behauptung abzutun. Sie benennt aber Folgen, und die lassen sich durchdenken. Schwer messbar heißt nicht, dass man gar nichts prüfen kann."},{"option":3,"text":"Auf die Quelle zu schauen ist oft ein guter Anfang, besonders bei Tatsachenbehauptungen. Wer die Idee zuerst vertreten hat und wie sie oder er auftritt, sagt aber nichts darüber, ob der Satz in sich aufgeht."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-a2-003","clusterId":"A","werkstueckRef":"A.12","stufe":3,"question":"Ein Redner sagt: „Mein Gedankenexperiment zeigt, dass Wasser ein Gedächtnis hat, denn man kann es widerspruchsfrei durchspielen.“ Was ist an diesem Schluss fehlerhaft?","options":["Widerspruchsfreiheit zeigt nur, dass die Idee denkbar und stimmig ist, nicht dass sie in der Wirklichkeit zutrifft.","Ein Gedankenexperiment taugt nur dann als Argument, wenn seine Annahmen vollständig mit der Wirklichkeit übereinstimmen, daher ist der Schluss wertlos.","Der Schluss ist nur dann gültig, wenn mindestens drei Personen das Szenario unabhängig voneinander durchgespielt und denselben Ausgang gefunden haben.","Dass sich eine Idee widerspruchsfrei durchspielen lässt, spricht eher gegen sie, weil die wirkliche Welt immer Widersprüche und Brüche enthält."],"correctIndex":0,"explanation":"Ein Gedankenexperiment prüft die logische Stimmigkeit einer Annahme, mehr nicht. Fällt eine Idee dabei durch, weil sie sich selbst widerspricht, muss man sie gar nicht erst an der Wirklichkeit testen. Besteht sie die Prüfung, ist sie damit noch nicht wahr: Nur weil eine Idee ein Gedankenexperiment überlebt, heißt das noch lange nicht, dass sie wahr ist. Ob Wasser ein Gedächtnis hat, entscheidet am Ende die Realität, nicht die Vorstellungskraft. Dabei sind Annahmen, die der Wirklichkeit widersprechen, durchaus erlaubt (Einstein ließ sich auf einem Lichtstrahl reiten), solange sie als Annahmen kenntlich bleiben und das Ergebnis nicht mit einem Beweis verwechselt wird.","coreRule":"⚡ Überleben im Gedankenexperiment heißt „möglich“, nicht „wahr“; entscheiden muss die Realität.","beleg":"Werkstück A.12 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Ein Gedankenexperiment prüft nur, ob eine Annahme in sich stimmig ist. Dass sie sich widerspruchsfrei durchspielen lässt, macht sie noch nicht wahr: Ob Wasser ein Gedächtnis hat, entscheidet die Wirklichkeit, nicht die Vorstellungskraft.","prueffrage":"Welche Messung oder Beobachtung könnte zeigen, dass der Redner mit seiner Behauptung danebenliegt?","rueckmeldung":[{"option":1,"text":"Strenge bei den Annahmen wirkt redlich. Gedankenexperimente dürfen aber wirklichkeitswidrige Annahmen nutzen, solange sie als Annahmen kenntlich bleiben. Der Fehler des Redners liegt woanders: Er hält ein Durchspielen für einen Beweis."},{"option":2,"text":"Dass andere zum selben Ergebnis kommen, wirkt wie eine Absicherung. Es zeigt aber nur, dass mehrere Köpfe dieselbe Idee stimmig finden, nicht dass sie in der Wirklichkeit gilt. Das Problem bleibt, egal wie viele es durchspielen."},{"option":3,"text":"Ein Funke Wahrheit steckt darin: Eine bestandene Prüfung macht eine Idee nicht wahr. Verdächtig wird sie dadurch aber nicht. Widerspruchsfreiheit ist eine Mindestbedingung für Ideen, sagt für sich aber nichts über die Wirklichkeit."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-a2-004","clusterId":"A","werkstueckRef":"A.12","stufe":4,"question":"Wie belastbar ist das Ergebnis einer solchen Rechnung mit offengelegten, aber geschätzten Annahmen?","options":["Die Rechnung widerlegt die behauptete Täuschung, sofern das Ergebnis deutlich ausfällt und die Zahlen plausibel klingen.","Sie zeigt, welche Konsequenzen die Behauptung unter den genannten Annahmen hätte; weil die Annahmen offenliegen, kann jeder sie nachrechnen, ändern und angreifen.","Sie ist kaum aussagekräftig, weil geschätzte Zahlen zu ungenau sind, um daraus eine Schlussfolgerung zu ziehen.","Sie wird erst belastbar, wenn die Schätzungen durch gemessene Werte ersetzt sind und keine Annahme mehr offen ist."],"correctIndex":1,"explanation":"Eine Rechnung mit Schätzwerten ist kein Beweis, aber auch nicht wertlos. Sie macht aus einer vagen Vorstellung ein Modell: Die Annahmen stehen offen auf dem Tisch, und jeder kann prüfen, ob sie vernünftig sind, und sie verändern. Dass die Zahlen Schätzungen sind, entwertet die Rechnung nicht, solange die Annahmen sichtbar sind und überprüft werden können. Ein reales Beispiel: Der Forscher David Robert Grimes rechnete 2016 die Mondlandungsverschwörung so durch. Er setzte rund 411.000 Mitwissende an (die NASA-Beschäftigten im Spitzenjahr 1965) und schätzte das Risiko des Verrats bewusst niedrig. Selbst dann wäre der Schwindel nach knapp vier Jahren mit über 95 Prozent Wahrscheinlichkeit aufgeflogen. Grimes selbst nennt die Zahlen grobe Größenordnungen, und das Modell nimmt an, alle Gezählten wären eingeweiht. Der Wert liegt in der Nachprüfbarkeit der Annahmen, nicht in einem Beweis.","coreRule":"⚡ Ein Gedankenexperiment wird zum Modell, wenn seine Annahmen offenliegen und angreifbar sind.","beleg":"Werkstück A.12 (Anwendung: Verschwörungsmythen); Fn. ga-grimes (Grimes 2016, PLOS ONE 11(1), e0147905, S. 8 und S. 11)","status":"entwurf","scenario":"Eine Forscherin schätzt für eine angebliche Jahrzehnte alte Täuschung grob die Zahl der Eingeweihten und das Risiko ein, dass jemand das Geheimnis ausplaudert. Sie rechnet beide Annahmen durch und legt sie in der Veröffentlichung offen. Ein Kritiker wendet ein: „Das sind doch nur geschätzte Zahlen, also ist die ganze Rechnung wertlos.“","kurz":"Die Rechnung ist kein Beweis, aber auch nicht wertlos: Sie zeigt, was die Behauptung unter den genannten Annahmen bedeuten würde. Weil diese offenliegen, kann jeder sie prüfen und ändern. Geschätzt heißt nicht wertlos, sondern angreifbar.","prueffrage":"Welche Zahlen stehen in der Rechnung, und würde sich das Ergebnis ändern, wenn man sie großzügig verschiebt?","rueckmeldung":[{"option":0,"text":"Ein deutliches Ergebnis wirkt wie ein Urteil. Doch die Rechnung zeigt nur, was unter den gewählten Annahmen folgt, und ist kein Beweis. Dass sie Zweifel begründet, heißt nicht, dass sie die Täuschung widerlegt."},{"option":2,"text":"Der Einwand hat einen wahren Kern: Schätzungen sind ungenau, und ein Beweis entsteht so nicht. Ungenau ist aber nicht wertlos, solange offenliegt, was angenommen wurde. Dann lässt sich prüfen, ob das Ergebnis auch bei anderen Zahlen hält."},{"option":3,"text":"Gemessene Werte wären natürlich besser. Wer Belastbarkeit aber erst ohne jede offene Annahme zugesteht, verlangt etwas, das kaum ein Modell erfüllt. Entscheidend ist, dass die Annahmen sichtbar und nachprüfbar sind, nicht dass sie gemessen sind."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): On the Viability of Conspiratorial Beliefs. PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905"},{"typ":"doi","kurz":"Grimes, D. R. (2016): Correction: On the Viability of Conspiratorial Beliefs. PLOS ONE 11(3), e0151003","oeffentlich":true,"doi":"10.1371/journal.pone.0151003"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-005","clusterId":"A","werkstueckRef":"A.13","stufe":1,"question":"Was würdest du als Nächstes tun?","options":["Beobachten, wohin die Leute beim Hinuntergehen schauen und was sie dabei erreichen wollen.","Die Schilder größer und auffälliger machen, weil die bisherigen offenbar zu leicht zu übersehen waren.","Alle Beschäftigten zu einer Sicherheitsunterweisung verpflichten, damit sie lernen, wie man eine Treppe richtig benutzt.","Die Unfälle weiter zählen und abwarten, ob sich bei mehr Daten ein Muster in der Unachtsamkeit der Betroffenen zeigt."],"correctIndex":0,"explanation":"Wenn ein Verhalten unerklärlich wirkt, ist „dumm und unachtsam“ die bequeme, aber leere Erklärung: Sie prüft nichts und erklärt nicht, warum drei Maßnahmen nichts geändert haben. Wer Menschen als vernünftig Handelnde annimmt, fragt stattdessen, welches Ziel ihr Verhalten sinnvoll macht, und beobachtet es. Naheliegend ist hier etwa, dass die Leute beim Hinuntergehen schon die belebte Kreuzung am Treppenende im Blick haben, um eine Lücke zu finden, und deshalb nicht auf die Stufen achten. Größere Schilder, Schulungen oder bloßes Weiterzählen setzen dagegen am Menschen an, obwohl das Problem in der Anlage aus Treppe und Flur liegen kann. Erst wenn man das Ziel kennt, lässt sich das System ändern, statt die Menschen ändern zu wollen.","coreRule":"⚡ Bevor du Menschen als dumm abstempelst, frag nach dem unsichtbaren Ziel hinter ihrem Verhalten.","quote":"Das Problem war nicht der Mensch, sondern die Treppe im Verhältnis zum Flur.","quoteLabel":"Merksatz:","beleg":"Werkstück A.13 (Einstiegsgeschichte „Die verfluchte Treppe“; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"In einem Bürogebäude häufen sich die Unfälle auf einer steilen Treppe. Am Fuß der Treppe kreuzen sich zwei stark befahrene Hauptflure. Vorsicht-Schilder, hellere Beleuchtung und rutschfeste Streifen haben nichts geändert, die Unfallrate ist seit Monaten unverändert hoch. Ein Manager sagt: „Unsere Leute sind einfach zu dumm und unachtsam für eine Treppe.“","kurz":"Wer das Verhalten als sinnvoll für die Handelnden annimmt, fragt nach ihrem Ziel und beobachtet es, statt „dumm und unachtsam“ zu unterstellen. So kann sich zeigen, dass der Blick schon der belebten Kreuzung am Treppenende gilt.","prueffrage":"Was haben Schilder, Beleuchtung und Streifen gemeinsam, und wurde vorher herausgefunden, warum die Leute gerade auf dieser Treppe stürzen?","rueckmeldung":[{"option":1,"text":"Wenn Schilder nichts bewirkt haben, scheinen größere die logische Steigerung. Doch auch Licht und Streifen blieben wirkungslos; solange unklar ist, wohin die Leute beim Hinuntergehen schauen, ist offen, ob sie ein größeres Schild beachten."},{"option":2,"text":"Eine Unterweisung unterstellt, dass die Leute nicht wissen, wie man eine Treppe benutzt. Dafür spricht nichts. Gilt ihr Blick schon der belebten Kreuzung, ändert auch eine Schulung daran wenig."},{"option":3,"text":"Mehr Daten wirken sachlich, nützen aber wenig, wenn sie nur Unfälle zählen und die Unachtsamkeit schon voraussetzen. Die Rate ist seit Monaten gleich hoch, neue Zahlen sagen nicht, was die Leute auf der Treppe eigentlich vorhaben."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a2-006","clusterId":"A","werkstueckRef":"A.13","stufe":2,"question":"Welche Frage bringt dich am ehesten zu einer brauchbaren Erklärung seines Verhaltens?","scenario":"Dein Onkel lässt sich seit Monaten bei einem Energieheiler behandeln und geht für diese Beschwerden nicht mehr zum Arzt. Er ist sonst ein nüchterner, vernünftiger Mensch. Du willst verstehen, warum er so handelt.","options":["„Wie kann ich ihm beweisen, dass er die Wirkung der Behandlung überschätzt und auf bloße Einbildung hereinfällt?“","„Warum durchschaut er den Unsinn nicht, obwohl er sich in allen anderen Fragen vernünftig verhält?“","„Wie seriös wirkt die Praxis, und welche Ausbildung kann der Heiler nachweisen?“","„Welches Problem löst der Heiler für ihn, etwa durch Zeit, Zuwendung, eine einfache Erzählung und Hoffnung?“"],"correctIndex":3,"explanation":"Wer ein Verhalten nur als Dummheit oder Charakterschwäche abtut, hat noch nichts erklärt. Die Frage nach dem Problem, das das Verhalten für die Person löst, macht sichtbar, was sie tatsächlich antreibt. Ein Heiler bietet oft ungeteilte Aufmerksamkeit, Empathie, eine verständliche Erzählung ohne Fachjargon und Hoffnung, wo die „Schulmedizin“ vielleicht nur noch von „Management“ spricht. Dann ist die Entscheidung des Onkels eher emotional und sozial rational als medizinisch dumm. Verstehen heißt dabei nicht gutheißen: Das Verständnis der Anreize ist der Schlüssel zu einem wirksamen Umgang mit dem Verhalten. Die anderen Fragen zielen auf Abwertung, Gegenbeweis oder die Einschätzung des Heilers und lassen die Anreize unberührt, die das Verhalten des Onkels tragen.","coreRule":"⚡ Frag, welches Bedürfnis ein Verhalten erfüllt, nicht, wie jemand so etwas glauben kann.","beleg":"Werkstück A.13 (Anwendung: Pseudomedizin; Aktivierungs-Frage)","status":"entwurf","kurz":"Sein Verhalten erklärst du erst, wenn du fragst, welches Problem es für ihn löst, etwa durch Zeit, Zuwendung und Hoffnung. Es nur als Dummheit oder Einbildung abzutun, erklärt nichts und lässt aus, was ihn tatsächlich antreibt.","prueffrage":"Seit wann geht dein Onkel zum Heiler statt zum Arzt, und was hat sich für ihn damals verändert?","rueckmeldung":[{"option":0,"text":"Gut möglich, dass dein Onkel die Wirkung überschätzt. Doch wer ihm das beweisen will und von „bloßer Einbildung“ spricht, will überzeugen und abwerten, nicht verstehen. Was ihn beim Heiler hält, bleibt dabei unberührt."},{"option":1,"text":"Dass er sich sonst vernünftig verhält, weckt zu Recht Zweifel an der Dummheits-Erklärung. Die Frage unterstellt aber schon, er durchschaue „Unsinn“ nicht, und erklärt damit nichts. Sein Verhalten bleibt ein Rätsel."},{"option":2,"text":"Seriosität und Ausbildung zu prüfen, ist durchaus sinnvoll, um den Heiler einzuschätzen. Warum der Onkel dort bleibt und den Arzt meidet, erklärt das jedoch nicht, denn die Anreize hinter seinem Verhalten bleiben außen vor."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Mercer, S. W.; Reilly, D.; Watt, G. C. M. (2002): The importance of empathy in the enablement of patients attending the Glasgow Homoeopathic Hospital. Br J Gen Pract 52(484), 901–905 (Abstract, PubMed)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/12434958/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a2-007","clusterId":"A","werkstueckRef":"A.13","stufe":3,"question":"Ein Kollege wirft dir vor: „Wenn du erklärst, warum Menschen extremistischen Ideologien folgen, entschuldigst du sie.“ Welche Antwort trifft den Denkfehler in diesem Vorwurf am besten?","options":["Eine Erklärung nennt Ursachen, eine Entschuldigung spricht von Verantwortung frei; wer die Ursachen kennt, kann das Verhalten sogar gezielter bekämpfen.","Der Vorwurf stimmt im Kern: Wer Gründe für schädliches Verhalten nennt, rückt die Handelnden in ein milderes Licht und sollte deshalb besser schweigen.","Der Vorwurf stimmt nur teilweise: Erklären ist nur dann unbedenklich, wenn man selbst nie ähnliche Motive hatte und dem Thema völlig neutral gegenübersteht.","Der Vorwurf trifft nur bei Ideologien zu: Bei Aberglauben und Alltagsverhalten darf man Gründe nennen, bei gefährlichen Überzeugungen schon nicht mehr."],"correctIndex":0,"explanation":"Der Vorwurf verwechselt zwei verschiedene Dinge: Verstehen, wie ein Verhalten zustande kommt, und Gutheißen, dass es richtig ist. Wer Anreize und Ursachen analysiert, beantwortet eine Sachfrage („Wie kommt es dazu?“), keine Wertungsfrage („Ist es in Ordnung?“). Man kann die systemischen Gründe für Rassismus untersuchen und ihn zugleich unmissverständlich bekämpfen. Ohne Verständnis der Ursachen bleibt die Gegenwehr dagegen oft wirkungslos, weil sie an den eigentlichen Anreizen vorbeigeht. Die anderen Antworten teilen den Fehler des Vorwurfs: Sie behandeln Erklären als eine Vorstufe der Entschuldigung, sei es pauschal, an Bedingungen geknüpft oder nur für bestimmte Themen.","coreRule":"⚡ Anreize zu verstehen heißt nicht, das Verhalten gutzuheißen.","beleg":"Werkstück A.13 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Erklären beantwortet die Sachfrage, wie es zu einem Verhalten kommt, und spricht niemanden von Verantwortung frei. Der Denkfehler setzt Verstehen mit Gutheißen gleich, dabei braucht Gegenwehr oft gerade die Kenntnis der Ursachen.","prueffrage":"Heißt eine Ärztin, die erklärt, wie eine Sucht entsteht, die Sucht damit gut?","rueckmeldung":[{"option":1,"text":"Gründe zu nennen kann sich beim Zuhören nach Milde anhören. Es beschreibt aber nur, wie es dazu kommt, und bewertet nichts. Schweigen würde zudem verhindern, die Anreize zu verstehen, an denen wirksame Gegenwehr ansetzen muss."},{"option":2,"text":"Eigene Motive und Voreingenommenheit können eine Analyse verzerren. Das betrifft aber ihre Qualität, nicht die Frage der Entschuldigung. Auch wer dem Thema nahesteht, erklärt nur, wie es dazu kommt, und heißt damit nichts gut."},{"option":3,"text":"Hier bleibt der Kern des Vorwurfs bestehen und wird nur auf bestimmte Themen eingegrenzt. Ob Aberglaube oder Extremismus: Eine Ursachenanalyse beantwortet immer die Sachfrage und fällt kein Urteil über Recht oder Unrecht."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Miller, A. G.; Gordon, A. K.; Buddie, A. M. (1999): Accounting for evil and cruelty: is to explain to condone? Personality and Social Psychology Review 3(3), 254–268 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0303_8","url":"https://pubmed.ncbi.nlm.nih.gov/15661676/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a2-008","clusterId":"A","werkstueckRef":"A.13","stufe":4,"question":"Was ist an dieser Überlegung fehlerhaft, und was wäre der bessere nächste Schritt?","options":["Er schließt aus „Ich kenne den Zweck nicht“ auf „Es gibt keinen Zweck“; besser wäre, zuerst herauszufinden, wozu der Ablauf eingeführt wurde, und dann zu entscheiden.","Er verlässt sich auf sein eigenes Urteil statt auf das der Mehrheit; besser wäre, abzuwarten, bis die Belegschaft den Ablauf mehrheitlich für lästig erklärt.","Er greift zu schnell in bestehende Abläufe ein; besser wäre, den Ablauf zunächst unverändert zu lassen, bis er einmal zu einem Problem geführt hat.","Er schaut zu sehr auf den Aufwand des Ablaufs; besser wäre, zunächst nur dessen Nutzen zu prüfen und die Kosten erst bei einem sichtbaren Problem zu betrachten."],"correctIndex":0,"explanation":"Dass niemand den Zweck nennen kann, zeigt nur, dass er nicht bekannt ist, nicht dass es keinen gibt. Ein Ablauf, der aufwendig und lästig wirkt, kann trotzdem ein Problem lösen, das man von außen nicht sieht (zum Beispiel eine frühere Panne oder eine Prüfpflicht; das sind hier nur denkbare Beispiele, über den konkreten Fall ist nichts bekannt). Wer ihn abschafft, ohne das zu klären, riskiert, genau dieses Problem zurückzuholen. Das ist die Logik von Chestertons Zaun: Man reißt einen Zaun quer über dem Weg erst ein, wenn man weiß, wozu er gebaut wurde. Das ist kein Verbot der Änderung, sondern die Forderung, zuerst den Zweck zu verstehen. Chesterton sprach von Einrichtungen und Gesetzen; die Übertragung auf Arbeitsabläufe ist eine Erweiterung.","coreRule":"⚡ Aus „Ich sehe den Zweck nicht“ folgt nicht „Es gibt keinen“: Kläre erst, wozu etwas da ist, dann entscheide.","beleg":"Werkstück A.13 (Kontext & Tiefe); Fn. ga-chesterton (Chesterton 1929, The Thing, Nachdruck 1946, S. 29)","status":"entwurf","scenario":"Ein neuer Abteilungsleiter findet in seiner Abteilung einen dreifachen Formularlauf für jede Bestellung. Niemand kann ihm sagen, wozu er gut ist. Er sagt: „Das ist offensichtlich sinnloser Aufwand, ich schaffe das ab diese Woche ab.“","kurz":"Dass niemand den Zweck nennt, zeigt nur, dass er unbekannt ist, nicht dass es keinen gibt. Der Fehler liegt im Schluss von „kenne ich nicht“ auf „gibt es nicht“; erst den Zweck klären, dann entscheiden.","prueffrage":"Seit wann arbeitet der Abteilungsleiter in dieser Abteilung, und wie viel von ihrer Geschichte kann er kennen?","rueckmeldung":[{"option":1,"text":"Die Stimmung der Belegschaft kann ein Hinweis sein. Dass ein Ablauf lästig wirkt, sagt aber nichts über seinen Zweck, und den kennt hier ja niemand. Auch ein eigenes Urteil ist nicht das Problem, sondern dass es ohne Kenntnis des Zwecks fällt."},{"option":2,"text":"Vorsicht beim Eingreifen ist richtig. Zu warten, bis der Ablauf selbst Ärger macht, klärt aber nie, wozu er da ist, und lässt womöglich unnötigen Aufwand ewig bestehen. Ändern darf er ihn, nur erst nach der Klärung des Zwecks."},{"option":3,"text":"Den Nutzen zu prüfen ist richtig, doch ihn allein zu betrachten und die Kosten zu übergehen, macht die Abwägung einseitig. Hier fehlt vor allem das Wissen, wozu der Ablauf dient, und das gilt es zuerst zu klären."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Chesterton, G. K. (1929): The Thing. London: Sheed & Ward, Essay „The Drift from Domesticity“","oeffentlich":false}],"thema":"Zusammenleben"},{"id":"qx-a2-009","clusterId":"A","werkstueckRef":"A.14","stufe":2,"question":"Was ist an dieser Begründung fürs Weitermachen fehlerhaft, und welche Frage prüft stattdessen, ob du weitermachen solltest?","scenario":"Seit drei Jahren pflegst du die Website eines Vereins, die kaum jemand besucht. Du hast schon rund 400 Stunden hineingesteckt. Auf der nächsten Sitzung sagt ein Mitglied: „Nach all der Arbeit wäre es doch schade, jetzt aufzuhören. Mach weiter, dann hat sich alles gelohnt.“","options":["Sie stützt sich auf bereits geleistete Stunden, die sich nicht zurückholen lassen. Besser prüft die Frage: „Würde ich heute, ohne diese Vorgeschichte, mit dem Projekt anfangen?“","Sie stützt sich auf die Meinung eines einzelnen Mitglieds, die nicht für alle gilt. Besser prüft die Frage: „Wie viele Mitglieder wollen die Website tatsächlich behalten?“","Sie stützt sich auf eine Prognose, die sich nicht belegen lässt. Besser prüft die Frage: „Wie viele zusätzliche Besucher bräuchte die Seite, damit die Mühe belohnt wird?“","Sie stützt sich auf Gefühle statt auf Zahlen zum bisherigen Aufwand. Besser prüft die Frage: „Wie viele Stunden hat das Projekt im Durchschnitt pro Monat gekostet?“"],"correctIndex":0,"explanation":"Das Argument begründet das Weitermachen mit dem, was schon investiert wurde: „Nach all der Arbeit …“. Das ist ein Red Flag der Versunkene-Kosten-Falle, denn die Begründung ist rückwärtsgewandt statt vorwärtsgewandt. Die Frage „Würde ich heute damit anfangen?“ blendet die Vergangenheit bewusst aus und bewertet ausschließlich die gegenwärtigen und zukünftigen Vor- und Nachteile. Lautet die Antwort „Nein“, ist das ein starkes Signal, dass dich nur die Vorgeschichte hält. Die übrigen Fragen bleiben bei Mitgliedermeinungen, Erwartungen oder der Auswertung des bisherigen Aufwands hängen. Sie prüfen nicht, ob du heute neu damit anfangen würdest.","coreRule":"⚡ Frag nicht „Wie viel habe ich schon investiert?“, sondern „Würde ich heute damit anfangen?“","beleg":"Werkstück A.14 (Kernidee; Red Flags)","status":"entwurf","kurz":"Die Begründung blickt nur auf die schon geleisteten Stunden zurück, die sich nicht zurückholen lassen. Ob du weitermachen solltest, zeigt die Frage, ob du heute ohne Vorgeschichte mit dem Projekt anfangen würdest.","prueffrage":"Was würde dem Verein fehlen, wenn die Website ab morgen nicht mehr gepflegt würde, und wer würde es bemerken?","rueckmeldung":[{"option":1,"text":"Ein einzelnes Mitglied spricht tatsächlich nicht für alle. Der Haken der Begründung liegt aber woanders: Sie stützt sich auf die geleistete Arbeit. Auch viele Stimmen mit demselben Argument änderten daran nichts."},{"option":2,"text":"Tatsächlich verspricht „dann hat sich alles gelohnt“ etwas, das niemand belegen kann. Der Kern ist aber der Verweis auf die geleistete Arbeit, und die Frage, wann sich „die Mühe“ auszahlt, rechnet die vergangenen Stunden weiter mit ein."},{"option":3,"text":"Die Stunden sind hier nicht unklar, die Zahl 400 steht ja fest. Der Fehler liegt darin, dass sie überhaupt als Grund zählen. Den Monatsaufwand auszuwerten bleibt in der Vergangenheit und sagt nicht, ob sich Weitermachen jetzt lohnt."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124–125","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a2-010","clusterId":"A","werkstueckRef":"A.14","stufe":3,"question":"Wer wendet die Null-Basis-Frage falsch an?","scenario":"Im vierten Jahr deines Medizinstudiums wird die Prüfungsphase hart. Du bist erschöpft und überlegst, ob du dir die sogenannte Null-Basis-Frage stellen solltest: „Würde ich heute, ohne meine bisherige Zeit zu zählen, noch einmal mit diesem Studium anfangen?“ Vier Kommilitonen schildern, wie sie die Frage nutzen.","options":["Jule bricht ab, weil ihr die Prüfungsphase zu anstrengend ist, obwohl sich an Ziel und Aussichten nichts geändert hat.","Tom wägt bei der Frage ausdrücklich auch die künftigen Vor- und Nachteile einer Fortsetzung ab.","Lena stellt die Frage auch einem Bekannten, der seit Jahren Geld in ein Hobbyprojekt steckt und überlegt, ob es sich künftig noch lohnt.","Jonas gibt eine liebgewonnene Gewohnheit auf, weil er auf die Frage ehrlich „Nein“ antwortet."],"correctIndex":0,"explanation":"Die Null-Basis-Frage soll versunkene Kosten und bloße Trägheit ausblenden und prüfen, ob eine Fortsetzung zu den heutigen Umständen und dem heutigen Wissen passt. Sie ist kein Freibrief, bei der ersten Anstrengung aufzugeben. Wer ein langes, schwieriges Vorhaben abbricht, obwohl sich nur die Mühe und nicht die Lage oder das Wissen geändert haben, wendet sie falsch an. Ausdauer ist für langfristige Ziele nötig. Tom, Lena und Jonas nutzen die Frage so, wie sie gedacht ist: Sie beurteilen die Zukunft statt der Vergangenheit und ziehen ehrlich Konsequenzen.","coreRule":"⚡ Der Check prüft veränderte Umstände, er ersetzt nicht Ausdauer bei Anstrengung.","beleg":"Werkstück A.14 (Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Die Null-Basis-Frage prüft, ob eine Fortsetzung zu heutigen Umständen und heutigem Wissen passt. Wer abbricht, nur weil es anstrengender wird, obwohl sich Lage und Wissen nicht geändert haben, verwechselt Mühe mit einem Grund zum Aufhören.","prueffrage":"Was weiß jede Person heute über ihr Vorhaben, das sie zu Beginn noch nicht wusste, und worauf stützt sie ihre Entscheidung?","rueckmeldung":[{"option":1,"text":"Die Frage blendet bereits investierte Zeit und Mühe aus, nicht die Zukunft. Gerade der Blick auf künftige Vor- und Nachteile ist ihr Zweck; wer so abwägt wie Tom, nutzt sie richtig."},{"option":2,"text":"Dass Lena die Frage auf das Hobbyprojekt eines Bekannten überträgt, wirkt zunächst ungewöhnlich. Die Frage zielt dort aber genau auf den künftigen Nutzen und lässt das bisher hineingesteckte Geld außen vor; das ist ihr Sinn."},{"option":3,"text":"Ein ehrliches „Nein“ ernst zu nehmen, ist gewollt, besonders bei Gewohnheiten, die oft nur aus Trägheit weiterlaufen. Dass Jonas Konsequenzen zieht, ist daher kein Fehler, sondern der Zweck der Frage."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"125","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-a2-011","clusterId":"A","werkstueckRef":"A.14","stufe":4,"question":"Eine Frau hängt seit zehn Jahren einer Lehre an, in die sie viel Geld und Lebenszeit gesteckt hat. Ein Freund fragt sie: „Stell dir vor, du hörtest heute zum ersten Mal davon. Würden dich die Beweise, die dir jetzt präsentiert werden, überzeugen, dein Leben dafür umzukrempeln?“ Warum ist diese Frage hier hilfreich, aber für sie zugleich besonders schwer zu beantworten?","options":["Sie prüft die Lehre allein anhand heutiger Beweise ohne Vorgeschichte; ein „Nein“ würde aber heißen, dass sie zehn Jahre lang falsch entschieden hat.","Sie rechnet der Frau vor, wie viel Geld und Zeit sie bereits verloren hat; dieser Verlust lässt sich aber nicht mehr beziffern.","Sie zwingt die Frau, ihre Zweifel vor den anderen Anhängern auszusprechen; das fällt ihr schwer, weil sie Ablehnung fürchtet.","Sie blendet die Vorgeschichte aus; bei Überzeugungen lässt sich diese aber nie von der heutigen Beweislage trennen."],"correctIndex":0,"explanation":"Die Frage löscht die Vergangenheit aus der Entscheidungs-Gleichung: Nur heutige Belege und künftiger Nutzen zählen, bisherige Investitionen nicht mehr. Genau das macht sie stark gegen die Versunkene-Kosten-Falle. Bei lange gehegten Überzeugungen ist sie aber schwer anzuwenden, denn ein „Nein“ hieße, jahrelang an einer schlechten Entscheidung festgehalten zu haben. Das erzeugt kognitive Dissonanz, und um ihr Selbstbild als gute Entscheiderin zu schützen, suchen Menschen in dieser Lage oft lieber Gründe, an der Lehre festzuhalten. Die Frage rechnet dabei keine Verluste vor, muss vor niemandem beantwortet werden, und die Trennung von Vorgeschichte und heutiger Beweislage ist schwer, aber nicht unmöglich.","coreRule":"⚡ Der Null-Basis-Check fragt: „Würde ich heute damit anfangen?“ Bei festgefahrenen Überzeugungen ist er kraftvoll, aber schwer anzuwenden.","beleg":"Werkstück A.14 (Anwendung: festgefahrene Überzeugungen; Verbindungen: Kognitive Dissonanz)","status":"entwurf","scenario":"","kurz":"Die Frage zählt nur heutige Belege und künftigen Nutzen, nicht das bereits Investierte. Schwer fällt die Antwort, weil ein „Nein“ hieße, zehn Jahre lang falsch entschieden zu haben, und dagegen sträubt sich das Selbstbild als kluge Entscheiderin.","prueffrage":"Was soll die Frau nach der Frage ihres Freundes in ihre Antwort einbeziehen, und was ausdrücklich nicht?","rueckmeldung":[{"option":1,"text":"Geld und Zeit stecken tatsächlich in der Lehre. Die Frage rechnet sie aber nicht vor, sie lässt sie bewusst außen vor. Schwer wird die Antwort, weil ein „Nein“ das Selbstbild als kluge Entscheiderin träfe."},{"option":2,"text":"Ablehnung durch andere Anhänger kann real sein. Doch die Frage stellt ihr ein Freund, nicht die Gruppe, und vor den Anhängern muss sie nichts aussprechen. Die Hürde liegt im Inneren: Ein „Nein“ würde ihr Bild als gute Entscheiderin erschüttern."},{"option":3,"text":"Dass die Frage die Vorgeschichte ausblendet, stimmt. Doch Vorgeschichte und heutige Beweislage lassen sich trennen, wenn auch mühsam. Schwer fällt die Antwort, weil ein „Nein“ eine frühere Entscheidung als schlecht entlarven würde."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Harmon-Jones, E.; Mills, J. (2019): An Introduction to Cognitive Dissonance Theory and an Overview of Current Perspectives on the Theory. In: Harmon-Jones, E. (Hg.): Cognitive Dissonance, 2. Aufl., APA (Leseprobe auf apa.org)","oeffentlich":true,"doi":"10.1037/0000135-001","url":"https://www.apa.org/pubs/books/Cognitive-Dissonance-Intro-Sample.pdf","seite":"3; 6–7","abruf":"2026-10-12"},{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"},{"typ":"doi","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie"},{"id":"qx-a2-012","clusterId":"A","werkstueckRef":"A.15","stufe":1,"question":"Eine Kollegin sagt: „Ein Schluss ist genau dann deduktiv, wenn er vom Allgemeinen zum Besonderen geht, und genau dann induktiv, wenn er vom Besonderen zum Allgemeinen geht.“ Du sollst prüfen, ob das stimmt. Welche Frage trennt deduktive und induktive Schlüsse am besten?","options":["Geht der Schluss vom Allgemeinen zum Besonderen oder umgekehrt? Die Richtung zeigt zuverlässig, welche Schlussart vorliegt.","Muss die Konklusion wahr sein, wenn die Prämissen wahr sind, oder ist sie nur wahrscheinlich? Die Richtung allein sagt darüber nichts.","Kommt der Schluss aus der Wissenschaft oder aus dem Alltag? Der Anwendungsbereich zeigt zuverlässig, welche Schlussart vorliegt.","Arbeitet der Schluss mit Zahlen und Formeln oder mit Beobachtungen? Das Material zeigt zuverlässig, welche Schlussart vorliegt."],"correctIndex":1,"explanation":"Die Richtungsregel scheitert an beiden Beispielen. Schluss (1) ist deduktiv, bleibt aber zwischen allgemeinen Sätzen. Schluss (2) ist induktiv, bleibt aber bei Einzelfällen, nämlich von bisher untersuchten Spinnen auf die nächste. Verlässlich trennt etwas anderes: Bei einem deduktiven Schluss muss die Konklusion wahr sein, wenn die Prämissen wahr sind. Bei einem induktiven Schluss bleibt sie auch bei wahren Prämissen nur wahrscheinlich, denn die nächste Spinne könnte eine Ausnahme sein. Auch Anwendungsbereich und Material taugen nicht als Kriterium: Induktion steckt ebenso in der Wissenschaft, und Deduktion lässt sich an Alltagsaussagen ohne Zahlen zeigen. Die Richtung ist deshalb nur eine Faustregel.","coreRule":"⚡ Deduktion zwingt, Induktion macht wahrscheinlich; die Richtung ist nur eine Faustregel.","beleg":"Werkstück A.15 (Kernidee); Fn. ga-deduktion-richtung (Shanahan, Internet Encyclopedia of Philosophy, Abschn. 9)","status":"entwurf","scenario":"Zwei Schlüsse zur Prüfung:\\n(1) „Alle A sind B, alle B sind C, also sind alle A auch C.“\\n(2) „Die zehn Spinnen, die ich bisher untersucht habe, haben acht Beine. Also hat auch die nächste Spinne, die ich finde, acht Beine.“","kurz":"Entscheidend ist, ob die Konklusion bei wahren Prämissen zwingend folgt oder nur wahrscheinlich ist. Die Richtungsregel täuscht: Schluss (1) bleibt bei allgemeinen Sätzen und ist deduktiv, Schluss (2) bleibt bei Einzelfällen und ist induktiv.","prueffrage":"Wovon handeln Prämissen und Konklusion in Schluss (1) und in Schluss (2): von allen Fällen einer Art oder von einzelnen Dingen?","rueckmeldung":[{"option":0,"text":"Als Faustregel hilft die Richtung oft weiter. Als Kriterium versagt sie schon hier: Schluss (1) bleibt bei allgemeinen Sätzen und ist deduktiv, Schluss (2) geht von Einzelfällen auf einen Einzelfall und ist induktiv."},{"option":2,"text":"Herkunft sagt wenig über die Schlussart: Induktion steckt ebenso in der Wissenschaft, und Deduktion lässt sich an Alltagsaussagen zeigen. Beide Beispiele hier ließen sich so nicht trennen."},{"option":3,"text":"Zahlen wirken wie ein greifbares Merkmal. Doch Schluss (1) kommt ohne Zahlen aus und ist deduktiv, während Schluss (2) Beine zählt und induktiv ist. Das Material entscheidet nicht, ob etwas zwingend folgt."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-013","clusterId":"A","werkstueckRef":"A.15","stufe":2,"question":"Was ist an diesem Schluss falsch?","scenario":"Dein Mitbewohner kommt nass nach Hause. Du denkst: „Wenn es regnet, wird man nass. Er ist nass. Also hat es geregnet.“","options":["Nichts, er ist gültig, weil beide Prämissen wahr sind und die Schlussfolgerung daher zwingend wahr sein muss.","Er ist ungültig, weil Nässe auch andere Ursachen haben kann und „Es hat geregnet“ daher nicht zwingend folgt.","Er ist eine saubere Induktion, weil er aus einer einzelnen Beobachtung ein sicheres allgemeines Gesetz ableitet.","Er ist ein Zirkelschluss, weil die Schlussfolgerung bereits wörtlich in der ersten Prämisse enthalten ist."],"correctIndex":1,"explanation":"„Wenn es regnet, wird man nass“ und „Er ist nass“ erlauben nicht den Schluss „Es hat geregnet“: Das ist der klassische Fehlschluss der Bejahung der Folge. Nass kann auch jemand sein, den ein Rasensprenger getroffen oder jemand mit einem Eimer übergossen hat. Eine gültige Deduktion wäre zwingend; diese ist es nicht.","coreRule":"⚡ Aus „Wenn A, dann B“ und „B“ folgt nicht „A“.","beleg":"Werkstück A.15 (Denkweg 1); Fn. ga-bejahung (Dowden, Internet Encyclopedia of Philosophy, „Affirming the Consequent“)","status":"entwurf","kurz":"Die Regel „Regen macht nass“ gilt nur in einer Richtung: Wer nass ist, war nicht zwingend im Regen, ein Rasensprenger oder ein Eimer Wasser tut es auch. Der Fehler ist, die Folge als Beleg für genau eine Ursache zu nehmen.","prueffrage":"Ist die Straße vor der Tür nass, und sind andere, die gerade von draußen kommen, ebenfalls nass?","rueckmeldung":[{"option":0,"text":"Beide Prämissen sind tatsächlich plausibel. Wahre Prämissen allein machen einen Schluss aber nicht zwingend: Entscheidend ist, ob die Schlussfolgerung aus ihnen folgt, und „nass“ führt nicht allein auf „Regen“."},{"option":2,"text":"Tatsächlich wird von einer Beobachtung auf eine Ursache geschlossen. Ein allgemeines Gesetz entsteht aber nicht, und Induktion liefert ohnehin keine Sicherheit. Der Schluss tritt als zwingende Folgerung auf und scheitert an seiner Form."},{"option":3,"text":"Das Wort „regnet“ steht tatsächlich schon in der ersten Prämisse, aber nur als Bedingung: Sie behauptet nicht, dass es geregnet hat. Der Schluss setzt sein Ergebnis also nicht voraus, er dreht die Wenn-Dann-Richtung um."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Affirming the Consequent“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-07"}],"thema":"Zusammenleben"},{"id":"qx-a2-014","clusterId":"A","werkstueckRef":"A.15","stufe":3,"question":"Ein Mitglied einer Gruppe argumentiert: „Alles, was unser Anführer sagt, ist wahr. Der Anführer sagt, die Welt gehe nächste Woche unter. Also geht sie unter.“ Du sollst die Schwachstelle benennen. Wo setzt du an?","options":["Bei der Form des Schlusses: Er schließt von der Folge auf die Bedingung und ist deshalb logisch ungültig.","Bei der Konklusion, denn aus einer Allaussage darf man grundsätzlich keinen Schluss auf einen Einzelfall ziehen.","Bei den Beobachtungen: Der Anführer hat bisher zu wenige Weltuntergänge erlebt, um sich sicher sein zu können.","Bei der ersten Aussage: Der Schluss folgt sauber aus ihr, aber niemand hat belegt, dass der Anführer immer recht hat."],"correctIndex":3,"explanation":"Formal ist der Schluss gültig: Wenn wirklich alles wahr ist, was der Anführer sagt, und er den Weltuntergang ankündigt, dann folgt der Weltuntergang zwingend. Der Aufbau entspricht dem klassischen „Alle Menschen sind sterblich, Sokrates ist ein Mensch, also ist Sokrates sterblich“. Ein gültiger Schluss ist aber nur so verlässlich wie seine Ausgangsaussage, und genau die ist hier unbelegt und in dieser Absolutheit kaum haltbar: Kein Mensch irrt nie. Wer nur die Form prüft, findet keinen Fehler und lässt das Gedankengebäude unangetastet. Die Prüfung muss bei der Prämisse ansetzen: Woher weiß man, dass der Anführer immer recht hat, und gibt es Belege für das Gegenteil, etwa frühere Vorhersagen, die nicht eingetroffen sind? Die anderen Ansätze scheitern: Der Schluss bejaht nicht die Folge, aus einer Allaussage darf man sehr wohl auf Einzelfälle schließen, und von Beobachtungen oder Stichproben ist hier gar nicht die Rede.","coreRule":"⚡ Prüfe bei einem logischen Argument immer auch die Prämissen, nicht nur die Form.","beleg":"Werkstück A.15 (Anwendung: Sekten & Kulte; Red Flags; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Schluss ist formal gültig, trägt aber nur so weit wie seine Ausgangsaussage. Dass der Anführer immer recht hat, ist unbelegt und kaum haltbar. Wer nur die Form prüft, findet keinen Fehler und übersieht die schwache Stelle.","prueffrage":"Wenn die erste und die zweite Aussage stimmen, muss dann auch die dritte stimmen?","rueckmeldung":[{"option":0,"text":"Bei einem Fehlschluss lohnt sich der Blick auf die Form, doch hier wird nicht von der Folge auf die Bedingung geschlossen, sondern von der Bedingung auf die Folge. Die Form ist gültig, der Fehler steckt woanders."},{"option":1,"text":"Die Konklusion ist das Unglaubliche am Satz, deshalb setzt man gern dort an. Aus einer Allaussage darf man aber sehr wohl auf einen Einzelfall schließen, so funktionieren gültige Schlüsse; der Mangel liegt in der Allaussage selbst."},{"option":2,"text":"Behauptungen auf Belege zu prüfen, ist richtig. Von Beobachtungen oder Stichproben ist hier aber keine Rede, und Weltuntergänge lassen sich ohnehin nicht sammeln. Zu prüfen ist die erste Aussage: Woher weiß man, dass der Anführer immer recht hat?"}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Zusammenleben"},{"id":"qx-a2-015","clusterId":"A","werkstueckRef":"A.15","stufe":4,"question":"Welche Aussage über den Schluss der Ärztin ist richtig?","options":["Sie schließt auf die beste Erklärung aller Beobachtungen; das Ergebnis ist nur wahrscheinlich und kann durch weitere Befunde widerlegt werden.","Sie wendet eine allgemeine Regel an und folgert daraus zwingend die Diagnose; wenn die Regel stimmt, muss die Diagnose stimmen.","Sie verallgemeinert aus vielen gesammelten Einzelfällen eine neue Regel über Grippe; die Schlussfolgerung gilt damit für alle ähnlichen Patienten.","Sie schließt aus den vielen passenden Symptomen auf die Diagnose; durch die Menge der Indizien ist der Schluss zwingend gültig."],"correctIndex":0,"explanation":"Der Schluss geht von mehreren Beobachtungen auf die Erklärung, die sie am besten verbindet. Er ist nicht zwingend und bildet auch keine neue Regel aus gezählten Fällen; er liefert nur Wahrscheinliches. Ein zwingender Schluss würde aus wahren Prämissen notwendig folgen, das ist hier nicht der Fall: Fieber, Husten und Gliederschmerzen passen auch zu anderen Erkrankungen. Auch viele passende Indizien erhöhen nur die Wahrscheinlichkeit, und ein weiterer Befund, etwa ein negativer Test, könnte die Diagnose kippen. Man nennt das einen Schluss auf die beste Erklärung; er ist eng verwandt mit dem, was der Philosoph Charles S. Peirce Abduktion nannte.","coreRule":"⚡ Frag bei einem Schluss auf eine Ursache: Ist er zwingend oder nur wahrscheinlich, und welche Erklärung passt zu allen Beobachtungen am besten?","beleg":"Werkstück A.15 (Denkweg 2); Fn. ga-abduktion (Douven, Stanford Encyclopedia of Philosophy, „Abduction“, Abschn. 1.1)","status":"entwurf","scenario":"Eine Ärztin sieht einen Patienten mit Fieber, Husten und Gliederschmerzen. In der Nachbarschaft sind mehrere Grippefälle bekannt. Sie schließt: „Das ist sehr wahrscheinlich Grippe.“","kurz":"Aus den Symptomen und den bekannten Fällen in der Nachbarschaft wählt sie die Erklärung, die alles am besten verbindet. Das ist wahrscheinlich, aber nicht zwingend, denn dieselben Beschwerden passen auch zu anderen Krankheiten.","prueffrage":"Worauf stützt die Ärztin ihr Urteil im Einzelnen, und was davon hat sie selbst gezählt oder getestet?","rueckmeldung":[{"option":1,"text":"Ärztliches Fachwissen wirkt wie eine feste Regel. Doch Fieber, Husten und Gliederschmerzen kommen auch bei anderen Erkrankungen vor, eine Regel, aus der Grippe zwingend folgt, gibt es nicht. Die Diagnose bleibt eine gut begründete Vermutung."},{"option":2,"text":"Hier wird keine neue Regel gebildet: Die Ärztin beurteilt einen einzelnen Patienten. Ihr Schluss gilt nur für ihn, nicht für alle ähnlichen, und er liefert wie jede Diagnose aus Symptomen nur Wahrscheinliches."},{"option":3,"text":"Richtig ist, dass sie von den Symptomen auf die Diagnose schließt. Viele Indizien machen den Schluss aber nicht zwingend, sondern nur wahrscheinlicher: Ein negativer Test könnte die Diagnose trotzdem kippen."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Douven, I.: Abduction. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/abduction/","abruf":"2026-10-07"}],"thema":"Gesundheit"},{"id":"qx-a2-016","clusterId":"A","werkstueckRef":"A.16","stufe":1,"question":"Zwei Menschen streiten heftig darüber, ob ein bestimmtes Nahrungsergänzungsmittel Krebs heilt. Die eine Person verweist auf mehrere unabhängige Studien, die andere sagt: „Mein Bauchgefühl und der Rat meines Gurus sagen mir, dass es wirkt.“ Der Streit dreht sich im Kreis. Was ist die hilfreichste Reaktion?","options":["Beide Seiten sammeln weitere Einzelfakten zum Mittel, bis die Faktenlage auf einer Seite erdrückend ist.","Beide klären zuerst, mit welchem Verfahren sich in dieser Art von Frage überhaupt zuverlässig zwischen Wirkung und Einbildung unterscheiden lässt.","Beide fragen, warum Menschen überhaupt an Wundermittel glauben wollen, und analysieren die psychologischen Motive des Gegenübers.","Beide einigen sich darauf, dass jeder seine eigene Wahrheit hat, und beenden den Streit ohne weitere Prüfung."],"correctIndex":1,"explanation":"Wenn zwei Seiten ihre Behauptungen mit völlig unterschiedlichen Verfahren rechtfertigen (hier: überprüfbare Daten gegen Bauchgefühl und Autorität), führt ein Streit über Einzelfakten selten weiter, denn jede Seite lässt andere Belege gelten. Erst wenn geklärt ist, welches Verfahren die Frage überhaupt entscheiden kann, kommt man weiter. Ob ein Stoff Krebs heilt, lässt sich nur mit öffentlich überprüfbaren Daten, Beobachtungen und Experimenten klären: Intuition kann helfen einzuschätzen, ob man einer Person vertraut, aber nicht, ob ein Molekül einen Tumor heilt. Mehr Fakten zu sammeln ändert daran nichts, solange das Verfahren strittig ist, und die Motive des Gegenübers zu analysieren beantwortet die Sachfrage nicht. „Jeder hat seine eigene Wahrheit“ behandelt eine prüfbare Sachfrage wie eine Geschmacksfrage und beendet den Streit, ohne sie zu klären.","coreRule":"⚡ Frag nicht nur „Was weißt du?“, sondern „Woher weißt du es?“ Wer über die Methode der Wahrheitsfindung streitet, streitet nicht mehr im Kreis.","beleg":"Werkstück A.16 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Wer mit Daten argumentiert und wer mit Bauchgefühl und Autorität, nutzt verschiedene Verfahren der Wahrheitsfindung; weitere Einzelfakten helfen da wenig. Erst wenn geklärt ist, welches Verfahren eine Heilwirkung belegen kann, lässt sich die Sachfrage entscheiden.","prueffrage":"Was hat der bisherige Austausch von Argumenten bewirkt, und woran ist er jedes Mal hängengeblieben?","rueckmeldung":[{"option":0,"text":"Mehr Fakten wirken wie der gründliche Weg. Solange aber die eine Seite auf Gefühl und Autorität baut, prallen auch erdrückende Zahlen ab, und der Streit kreist weiter. Zuerst muss geklärt sein, was überhaupt als Beleg zählt."},{"option":2,"text":"Die Motive des Gegenübers zu ergründen kann interessant sein, entscheidet aber nicht, ob das Mittel wirkt. Es verschiebt den Streit von der Sache auf die Person und lässt die Frage nach dem geeigneten Verfahren unberührt."},{"option":3,"text":"Jedem seine eigene Wahrheit zuzugestehen, wirkt respektvoll. Ob ein Stoff Krebs heilt, ist aber keine Geschmacksfrage, sondern lässt sich prüfen. Wer den Streit hier abbricht, lässt die Frage offen, statt sie zu klären."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit"},{"id":"qx-a2-017","clusterId":"A","werkstueckRef":"A.16","stufe":2,"question":"Was ist jetzt der klügste nächste Schritt?","scenario":"Du diskutierst seit einer Stunde mit einem Bekannten über einen Verschwörungsmythos. Du bringst Studien, er winkt ab: „Die gehören doch alle zum System.“ Jede neue Quelle wird auf dieselbe Weise abgelehnt.","options":["Noch mehr Fakten und Studien nennen, bis die schiere Menge die Gegenseite endlich überzeugt und der Streit entschieden ist.","Zugeben, dass es verschiedene gleichwertige Wege des Wissens gibt, um den Streit friedlich und ohne Gesichtsverlust zu beenden.","Erst über die Methode reden: Welches Verfahren halten wir beide in dieser Frage für das verlässlichste, und was würde ihn umstimmen?","Die Quellen der Gegenseite pauschal als unzuverlässig erklären, damit nur noch die eigenen Quellen im Gespräch zählen."],"correctIndex":2,"explanation":"Wenn jede Gegenevidenz von vornherein als Teil der Verschwörung gilt, können weitere Fakten nichts bewirken: Ihr benutzt zwei verschiedene Verfahren, um zwischen wahr und falsch zu unterscheiden. Solange das nicht geklärt ist, redet ihr aneinander vorbei, weil jede Seite andere Beweise gelten lässt. Sinnvoll ist deshalb, zuerst die Methode zu besprechen: Wie lässt sich in dieser Art von Frage am verlässlichsten die Wahrheit herausfinden, und unter welchen Umständen würde er seine Meinung ändern? Noch mehr Studien zu nennen, wiederholt nur den Fehlversuch. Zuzugeben, alle Wege des Wissens seien gleichwertig, ist falsch: Ein Verfahren, das sich an der Realität prüfen lässt und Fehler korrigiert, ist verlässlicher als eines, das keine Gegenprobe zulässt. Und die Quellen der anderen Seite pauschal abzuwerten, ist derselbe Denkfehler, nur mit vertauschten Rollen.","coreRule":"⚡ Wenn Fakten nichts bewirken, klärt zuerst die Methode der Wahrheitsfindung.","quote":"","quoteLabel":"","beleg":"Werkstück A.16 (Anwendung; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Wenn jede Gegenquelle als „System“ gilt, können weitere Fakten nichts bewirken, denn ihr nutzt verschiedene Maßstäbe für wahr und falsch. Erst die Frage, welches Verfahren ihr beide gelten lasst und was ihn umstimmen würde, öffnet das Gespräch wieder.","prueffrage":"Wie hat er auf jede bisher genannte Studie reagiert, und hat sich daran im Lauf der Stunde etwas geändert?","rueckmeldung":[{"option":0,"text":"Weitere Studien scheinen zu helfen, weil Belege sonst überzeugen. Hier wird aber jede Quelle schon vorab abgetan, also läuft jede weitere Studie ins Leere. Das wiederholt nur den Fehlversuch der letzten Stunde."},{"option":1,"text":"Ein freundlicher Ton ist wertvoll, aber der Preis wäre hoch. Die Wege des Wissens sind nicht gleichwertig: Ein Verfahren, das sich an der Realität prüfen lässt und Fehler korrigiert, ist verlässlicher als eines ohne Gegenprobe."},{"option":3,"text":"Seine Quellen pauschal abzuwerten, scheint nur fair, weil er es mit deinen ebenso macht. Genau das ist aber derselbe Denkfehler mit vertauschten Rollen: Geklärt wird dadurch nichts, und der Streit verhärtet sich eher."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Zusammenleben"},{"id":"qx-a2-018","clusterId":"A","werkstueckRef":"A.16","stufe":3,"question":"Du steigst in ein Flugzeug und vertraust der Pilotin, ohne ihre Berechnungen nachzuprüfen. Ein Bekannter sagt: „Das ist doch genauso unkritisch wie der blinde Glaube an einen Guru. Wer wirklich rational ist, vertraut nur dem, was er selbst überprüft hat.“ Was ist an seinem Einwand fehlerhaft?","options":["Er setzt jedes Vertrauen in Fachleute mit blindem Guruglauben gleich, obwohl entscheidend ist, ob die Quelle nachprüfbar und korrigierbar ist und zur Art der Frage passt.","Er übersieht, dass Autorität nur dann zuverlässig ist, wenn sie auf einer langen religiösen oder kulturellen Tradition beruht und sich bewährt hat.","Er verlangt zu wenig, denn Vertrauen in eine Pilotin wäre erst berechtigt, wenn jede ihrer Berechnungen vorab von der gesamten Öffentlichkeit geprüft wurde.","Er übersieht, dass das Bauchgefühl bei Fragen der Flugsicherheit die verlässlichere Quelle wäre, weil Gefühle keine Rechenfehler machen und schneller sind."],"correctIndex":0,"explanation":"Vertrauen ohne eigene Nachprüfung ist nicht automatisch ein Denkfehler. Einer erfahrenen Pilotin vertrauen wir, weil ihr Können geprüft wurde, ihre Arbeit kontrolliert wird und Fehler auffallen und korrigiert werden können. Beim Guru gilt dagegen oft: Zweifel ist verboten, und widersprüchliche Evidenz wird umgedeutet, bis sie wieder zur Lehre passt. Entscheidend ist also, ob die Quelle nachprüfbar und korrigierbar ist und ob die Methode zur Art der Frage passt. Problematisch wird es dort, wo Bauchgefühl oder unprüfbare Autorität Sachfragen beantworten sollen, etwa ob ein Molekül ein Krebsgeschwür heilt oder ob Impfungen sicher sind.","coreRule":"⚡ Vertrauen in Autorität und Intuition ist nicht per se falsch: Es kommt darauf an, ob die Quelle nachprüfbar und korrigierbar ist und zur Art der Frage passt. Fragen, die nur Daten beantworten, entscheiden weder Gefühl noch Guru.","beleg":"Werkstück A.16 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Fachleuten ohne eigene Nachprüfung zu vertrauen ist nicht schon Guruglauben. Entscheidend ist, ob die Quelle nachprüfbar und korrigierbar ist und zur Art der Frage passt; der Denkfehler liegt darin, jedes Vertrauen in einen Topf zu werfen.","prueffrage":"Wie viel von dem, was der Bekannte täglich für wahr hält, hat er selbst überprüft?","rueckmeldung":[{"option":1,"text":"Dass sich eine Quelle bewährt hat, spricht durchaus für sie. Alter oder religiöse Tradition garantiert aber nichts: Auch Gurus berufen sich darauf. Maßgeblich ist, ob die Quelle nachprüfbar und korrigierbar ist und zur Frage passt."},{"option":2,"text":"Die Forderung klingt streng und damit besonders gründlich. Sie verlangt aber das Unmögliche und ist gar nicht nötig: Berechtigtes Vertrauen setzt voraus, dass Prüfung und Korrektur möglich sind, nicht dass alle jede Rechnung vorab geprüft haben."},{"option":3,"text":"Intuition ist im Alltag oft nützlich und schnell. Ob ein Flugzeug sicher fliegt, kann aber kein Gefühl entscheiden, und Gefühle irren sich durchaus. Bei Fragen der objektiven Realität sind Daten und überprüfbare Methoden die bessere Quelle."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Epistemological Problems of Testimony (2021)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/testimony-episprob/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-019","clusterId":"A","werkstueckRef":"A.16","stufe":4,"question":"Welche Frage deckt am besten auf, ob die Behauptung des Anbieters wissenschaftlich begründet ist oder nur so klingt?","options":["Wie professionell und wissenschaftlich klingt die Sprache, in der der Anbieter seine Methode beschreibt?","Wie viele begeisterte Kunden haben die Methode bereits ausprobiert und davon berichtet?","Wie bekannt und anerkannt ist der Entwickler der Methode in seinem Fachgebiet?","Unter welchen Ergebnissen wäre die Methode widerlegt, und kann das jemand unabhängig nachprüfen?"],"correctIndex":3,"explanation":"Entscheidend ist die Methode der Begründung, nicht das Vokabular. Der Anbieter ahmt die Sprache der Wissenschaft nach (Studien, Fachjargon), stützt sich aber auf Autorität (den Entwickler) und Intuition (die Erlebnisberichte der Kunden). Eine wissenschaftliche Begründung erkennt man an zwei Merkmalen: Sie ist falsifizierbar, man kann also sagen, welches Ergebnis sie widerlegen würde, und sie ist öffentlich überprüfbar, jeder kann die Prüfung wiederholen. Klingt die Sprache fachlich, sagt das nichts über die Methode. Viele begeisterte Berichte sind Anekdoten, die jede Behauptung stützen können. Und der Ruf eines Entwicklers ersetzt keine Prüfung, denn Ansehen ist Autorität und kein Beleg.","coreRule":"⚡ Prüfe nicht den Jargon, sondern auf welcher Methode eine Behauptung wirklich ruht.","beleg":"Werkstück A.16 (Anwendung: Pseudowissenschaft; Weg 1 bis 3; Prinzipien Falsifizierbarkeit und öffentliche Überprüfbarkeit)","status":"entwurf","scenario":"Ein Anbieter wirbt für seine „Energie-Methode“. Er verweist auf „Studien“ und benutzt viel Fachjargon. Fragt man, warum die Methode wirkt, antwortet er: „So hat es der Entwickler der Methode festgelegt, und unsere Kundinnen und Kunden berichten begeistert von ihren Erfahrungen.“","kurz":"Eine wissenschaftliche Begründung erkennt man daran, dass sie widerlegbar und öffentlich überprüfbar ist. Fachjargon, der Ruf des Entwicklers und begeisterte Berichte wirken überzeugend, ersetzen aber keine solche Prüfung.","prueffrage":"Welche Gründe nennt der Anbieter, wenn man ihn nach der Wirkung fragt, und woher stammt jeder davon?","rueckmeldung":[{"option":0,"text":"Fachsprache wirkt wie ein Gütesiegel, weil sie nach Prüfung klingt. Sie sagt aber nichts darüber, ob die Methode geprüft wurde: Jargon lässt sich beliebig nachahmen, ohne dass dahinter eine Untersuchung steht."},{"option":1,"text":"Viele Erfahrungsberichte sind greifbar und wirken überzeugend. Sie sind aber Anekdoten und passen zu fast jeder Behauptung, ob sie stimmt oder nicht. Auch die Zahl der Berichte erklärt nicht, ob die Methode die Ursache der Begeisterung ist."},{"option":2,"text":"Ein bekannter Entwickler weckt Vertrauen, und Fachwissen zählt durchaus. Ansehen ist aber Autorität und keine Prüfung: Auch eine angesehene Person kann sich irren, und ob die Methode wirkt, zeigt nur eine überprüfbare Untersuchung."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit"},{"id":"qx-a2-020","clusterId":"A","werkstueckRef":"A.17","stufe":1,"question":"Eine Studentin sagt: „Ich hab den Text zweimal gelesen, aber ich kapier ihn nicht, ich bin einfach schlecht in Statistik.“ Was würde jemand mit gutem Blick auf das eigene Denken stattdessen tun?","options":["Sie fragt sich, an welcher Stelle sie den Faden verloren hat, und sucht gezielt eine einfachere Erklärung genau dafür.","Sie liest den ganzen Text ein drittes Mal in der Hoffnung, dass sich das Verständnis durch Wiederholung einstellt.","Sie wechselt das Thema und kehrt erst zur Statistik zurück, wenn sie sich bereit und gelassener fühlt.","Sie nimmt sich vor, beim nächsten Lesen aufmerksamer und konzentrierter zu sein und nicht abzuschweifen."],"correctIndex":0,"explanation":"„Ich hab’s nicht verstanden“ ist ein pauschales Urteil, aus dem sich nichts ableiten lässt. Wer das eigene Verstehen überwacht, benennt, wo genau es abgerissen ist, und sucht gezielt eine andere Quelle für genau diesen Abschnitt. Die übrigen Wege ändern die Strategie nicht und benennen die Stelle nicht.","coreRule":"⚡ Gutes Denken über das eigene Denken bedeutet: genau benennen, wo es hakt, und dann die Strategie wechseln, statt sich pauschal als „schlecht darin“ abzustempeln.","quote":"","quoteLabel":"","beleg":"Werkstück A.17 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"„Ich kapier das nicht“ lässt sich nicht bearbeiten, die Stelle, an der der Faden riss, schon. Wer sie benennt, kann gezielt dafür eine andere Erklärung suchen, statt nur mehr vom Gleichen zu tun.","prueffrage":"Was hat die Studentin bisher unternommen, um den Text zu verstehen, und was hat sich zwischen erstem und zweitem Lesen geändert?","rueckmeldung":[{"option":1,"text":"Wiederlesen fühlt sich fleißig an und kann beim ersten Verstehen helfen. Nach zwei erfolglosen Durchgängen bleibt die Strategie aber dieselbe, und die Stelle, an der es hakt, bleibt unbenannt."},{"option":2,"text":"Etwas Abstand kann entlasten, das stimmt. Das Thema zu wechseln, bis man sich bereit fühlt, klärt aber nicht, was unklar war, und die Lücke ist beim Zurückkommen noch da."},{"option":3,"text":"Aufmerksamer zu lesen ist ein vernünftiger Wunsch. Der Vorsatz bleibt aber allgemein: Er sagt nicht, wo das Verstehen abriss, und ändert das Vorgehen nicht."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-a2-021","clusterId":"A","werkstueckRef":"A.17","stufe":2,"question":"Du liest einen Fachtext und verlierst im Abschnitt über Statistik den Faden. Welche Reaktion nutzt das Nachdenken über das eigene Lernen am besten?","scenario":"Du arbeitest dich durch einen Fachtext. Der Anfang war klar, doch im Abschnitt über Statistik kommst du nicht mehr mit. Du hast noch eine knappe Stunde Zeit.","options":["Du stellst fest, dass du Statistik einfach nicht kannst, und liest hoffnungsvoll weiter.","Du benennst, bis wohin du verstanden hast, und gehst gezielt diesen Abschnitt noch einmal an.","Du liest den ganzen Text sofort von vorn, bis du dir bei jeder Stelle sicher bist.","Du liest zügig weiter, um den Text ganz durchzuhaben, und prüfst erst am Ende."],"correctIndex":1,"explanation":"Wer sein eigenes Verständnis überwacht, merkt nicht nur, dass etwas nicht klappt, sondern kann genau sagen, wo es aussetzt. Erst diese Genauigkeit erlaubt eine passende Gegenmaßnahme: den fraglichen Abschnitt noch einmal ansehen oder eine einfachere Quelle suchen. Das pauschale Urteil „ich bin einfach schlecht darin“ ist dagegen keine Diagnose, sondern ein Etikett. Es benennt weder eine Stelle noch eine Strategie, die man ändern könnte. Auch ein Neustart ganz von vorn oder ein Weiterlesen ohne Prüfung setzt nicht an der Stelle an, an der das Verständnis tatsächlich abbrach.","coreRule":"⚡ Benenne genau, wo dein Verständnis endet, und passe dann deine Strategie an.","beleg":"Werkstück A.17 (Anwendung: Beim Lernen & Verstehen; Red Flags)","status":"entwurf","kurz":"Wer genau sagen kann, bis wohin er verstanden hat, findet die Stelle, an der es aussetzt, und kann dort gezielt ansetzen. Der naheliegende Fehler ist das pauschale Urteil „Ich kann das nicht“: Es klingt nach Einsicht, nennt aber weder Stelle noch Strategie.","prueffrage":"Wie viel Zeit bleibt dir, und für welchen Teil des Textes brauchst du sie wirklich?","rueckmeldung":[{"option":0,"text":"Zu bemerken, dass etwas nicht klappt, ist ein richtiger erster Schritt. „Ich kann Statistik einfach nicht“ ist aber nur ein Etikett: Es nennt keine Stelle und keine Strategie, die man ändern könnte, und das Weiterlesen lässt die Lücke bestehen."},{"option":2,"text":"Gründlichkeit ist ein guter Antrieb, und Wiederholen kann helfen. Hier kostet ein Neustart aber viel Zeit, obwohl der Anfang klar war. Er setzt nicht dort an, wo das Verständnis tatsächlich abbrach."},{"option":3,"text":"Bei knapper Zeit wirkt Fertigwerden vernünftig. Wer aber ohne Prüfung weiterliest, lässt die Abbruchstelle unbearbeitet, und das Fehlende fällt erst am Ende auf, wenn die Zeit womöglich nicht mehr reicht."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-a2-022","clusterId":"A","werkstueckRef":"A.17","stufe":3,"question":"Was erklärt das am besten?","options":["Nachdenken über das eigene Denken bringt im Sport grundsätzlich nichts, auch nicht im Training und in der Pause.","Die Selbstprüfung kommt am falschen Ort und zur falschen Zeit: Wo Sekundenbruchteile zählen, kostet sie Reaktionszeit, und die Spielerin zögert.","Die Torhüterin denkt nicht gründlich genug über ihr Denken nach; mit noch mehr Selbstbeobachtung während des Wurfs würde sie sicherer.","Die Unsicherheit hat mit der Selbstbeobachtung wenig zu tun und liegt vermutlich an der Tagesform der Torhüterin."],"correctIndex":1,"explanation":"Nachdenken über das eigene Denken (Fachbegriff: Metakognition) kann in Situationen hinderlich sein, die schnelle, intuitive Entscheidungen erfordern; Sport und Notfälle sind typische Beispiele. Solche Selbstprüfung ist langsam und anstrengend: Wo Sekundenbruchteile zählen, kostet sie Zeit, man analysiert, statt zu reagieren, und zögert. Das Werkzeug an sich bleibt nützlich, es kommt auf den passenden Ort und Zeitpunkt an, etwa im Training oder in der Pause. Wer „mehr davon“ als Lösung vorschlägt, wiederholt den Fehler, und wer das Werkzeug ganz verwirft, schüttet das Kind mit dem Bade aus.","coreRule":"⚡ Selbstprüfung gehört in ruhige Momente; wo Sekundenbruchteile zählen, zählt das Handeln.","beleg":"Werkstück A.17 (Der Kipppunkt; Anwendung)","status":"entwurf","scenario":"Die Torhüterin einer Handballmannschaft will nach jedem Gegentor ihre Entscheidungen verbessern. Im Training, in der Halbzeitpause und bei der Videoanalyse prüft sie ihre Entscheidungen gründlich, und dort bringt ihr das viel. Inzwischen prüft sie auch im Spiel bei jedem Wurf zuerst, was sie gerade denkt und fühlt, welche Strategie sie nutzt und ob die zu ihr passt. Das Team kassiert viele Tore, sie wirkt unsicher.","quote":"","quoteLabel":"","kurz":"Im Wurf bleiben nur Sekundenbruchteile, und Selbstprüfung ist langsam: Wer erst analysiert, was er denkt und fühlt, zögert. Mehr Reflexion ist also nicht immer besser; sie nützt dort, wo Zeit bleibt, etwa im Training.","prueffrage":"Wie hat die Torhüterin gehalten, bevor sie im Spiel mit dieser Selbstprüfung begann, und wie seitdem?","rueckmeldung":[{"option":0,"text":"Im Wurf stört die Selbstprüfung tatsächlich, das ist der richtige Kern. Im Training, in der Halbzeitpause und bei der Videoanalyse bringt ihr dieselbe Gründlichkeit aber viel; es kommt auf Ort und Zeitpunkt an."},{"option":2,"text":"Mehr Selbstbeobachtung klingt nach einer Lösung, wenn man das Zögern für Mangel an Gründlichkeit hält. Das Zögern entsteht aber gerade durch die Prüfung im Wurf, und mehr davon würde die Verzögerung eher noch verstärken."},{"option":3,"text":"Schwankende Tagesform gibt es im Sport, und sie liegt als Erklärung nahe. Für sie spricht hier aber nichts, eine andere Erklärung passt dagegen genau: Die Torhüterin prüft ihr Denken in dem Moment, in dem Reaktion gefragt ist."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Worthy, D. A.; Markman, A. B.; Maddox, W. T. (2009): Choking and excelling under pressure in experienced classifiers. Attention, Perception & Psychophysics 71(4), 924–935 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2708085/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"450","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-a2-023","clusterId":"A","werkstueckRef":"A.18","stufe":1,"question":"Zwei Personen reagieren auf eine neue Meldung: „Ein Präparat soll Erkältungen halbieren.“ Person A sagt: „Zeig mir eine kontrollierte Studie, die das belegt. Bis dahin halte ich die Aussage für unbewiesen. Wenn die Daten stimmen, ändere ich meine Meinung.“ Person B sagt: „Das ist Unsinn, das stimmt nie. Egal, welche Studie du bringst: Die ist gekauft.“ Was unterscheidet die beiden Haltungen im Kern?","options":["A macht sein Urteil vom Prüfergebnis abhängig und würde es ändern; B hat das Ergebnis schon festgelegt und wertet jeden Beleg ab.","A glaubt grundsätzlich keiner Aussage und prüft deshalb nichts; B glaubt nur Aussagen, die ihm persönlich gefallen.","A hält die Behauptung vorab für falsch und wartet auf Bestätigung; B will die Belege vor einem Urteil erst genau prüfen.","A lehnt Aussagen ab, die er nicht versteht, und prüft sie nie; B lehnt nur Aussagen ab, die von Firmen stammen."],"correctIndex":0,"explanation":"Person A legt fest, was sie überzeugen würde, und hält ihr Urteil bis dahin zurück. Das ist eine Methode: Die Stärke der Überzeugung richtet sich nach der Stärke der Belege. Person B hat die Schlussfolgerung schon gefasst und arbeitet sich rückwärts: Jeder widersprechende Beleg wird im Voraus abgewertet, damit das Ergebnis nicht gefährdet wird. Eine solche Position ist gegen Evidenz immun und deshalb keine Prüfung, sondern die Verteidigung eines fertigen Ergebnisses. Pauschales Misstrauen gegenüber allem wäre ebenfalls keine Methode, sondern Zynismus. Daraus folgt eine Prüffrage: Welcher Beleg würde die Haltung ändern?","coreRule":"⚡ Ein Skeptiker prüft mit offener Methode und kann sagen, was ihn umstimmen würde; ein Leugner verteidigt ein fertiges Ergebnis.","quote":"","quoteLabel":"","beleg":"Werkstück A.18 (Kernidee; Kontext & Tiefe); Fn. ga-leugnung (Hansson 2017, Studies in History and Philosophy of Science 63, S. 39–47)","status":"entwurf","scenario":"","kurz":"A hält sein Urteil zurück und nennt, was ihn überzeugen würde. B hat das Ergebnis schon gefasst und wertet jeden Beleg vorab ab. Der Unterschied liegt nicht im Misstrauen, sondern darin, ob ein Befund das Urteil noch ändern kann.","prueffrage":"Was sagt jede der beiden Personen über eine Studie, die es noch gar nicht gibt?","rueckmeldung":[{"option":1,"text":"Wer alles anzweifelt, wirkt vorsichtig. A prüft aber gerade: Er nennt eine kontrollierte Studie als Maßstab und würde seine Meinung ändern. Bei B liegt das Problem nicht im Gefallen, sondern darin, dass er jeden Beleg im Voraus abwertet."},{"option":2,"text":"Hier sind die Haltungen vertauscht. A hält die Aussage nur für unbewiesen, nicht für falsch, und ändert sein Urteil bei guten Daten. B will die Belege nicht abwarten, sondern hat sein Urteil schon gefällt und wertet jede Studie ab."},{"option":3,"text":"A lehnt nichts ab, sondern verlangt einen Beleg und urteilt erst danach. B lehnt nicht bloß Firmenquellen ab, er erklärt jede Studie vorab für gekauft. Entscheidend ist, ob ein Befund das Urteil noch ändern könnte."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Hansson, S. O. (2017): Science denial as a form of pseudoscience. Studies in History and Philosophy of Science Part A 63, 39–47","oeffentlich":false,"doi":"10.1016/j.shpsa.2017.05.002"}],"thema":"Gesundheit"},{"id":"qx-a2-024","clusterId":"A","werkstueckRef":"A.18","stufe":2,"question":"Welche Frage prüft seine Behauptung am besten?","scenario":"Auf einer Feier erzählt dir ein Astrologe begeistert, die Stellung der Planeten sage seit Jahren zuverlässig voraus, was im Leben seiner Kundschaft geschieht.","options":["„Wie kannst du so einen Unsinn glauben, der doch längst als widerlegt gilt?“","„Hast du Beispiele, in denen deine Vorhersagen eingetroffen sind? Das reicht mir als Beleg.“","„Wie wirken die Planeten auf mich, und gibt es Tests mit Treffern über dem Zufall?“","„Welche Ausbildung hast du, und in welchen Medien wurdest du als Experte zitiert?“"],"correctIndex":2,"explanation":"Eine Behauptung wird geprüft, indem man fragt, welcher Mechanismus sie erklären soll und ob kontrollierte Studien zeigen, dass die Vorhersagen besser sind als reiner Zufall. Einzelne eingetroffene Vorhersagen sind kein Beleg, denn ohne Vergleich mit dem Zufall lässt sich nicht sagen, ob die Treffer mehr sind als Glück. Fragen nach Ausbildung oder Medienauftritten prüfen die Person, nicht die Behauptung. Spott ersetzt die sachliche Prüfung, auch wenn die Skepsis berechtigt ist: Astrologie hat in kontrollierten Tests bisher keine Treffer über dem Zufall gezeigt. Die Frage nach solchen Tests lässt das Gegenüber selbst nachsehen, statt es nur abzuwerten.","coreRule":"⚡ Frag nach Mechanismus und kontrollierten Tests, nicht nach dem Ruf des Behauptenden.","beleg":"Werkstück A.18 (Anwendung: Gegenüber Pseudowissenschaft & Esoterik; Red Flags)","status":"entwurf","kurz":"Eine Behauptung prüft man, indem man nach dem Wirkmechanismus fragt und danach, ob kontrollierte Tests Treffer über dem Zufall zeigen. Eingetroffene Vorhersagen wirken überzeugend, sagen ohne Vergleich mit dem Zufall aber nicht, ob mehr als Glück im Spiel ist.","prueffrage":"Welche Vorhersagen hat er in den letzten Jahren gemacht, und wurden sie aufgeschrieben, bevor sich zeigte, ob sie eintreffen?","rueckmeldung":[{"option":0,"text":"Skepsis ist hier gut begründet, doch Spott prüft nichts. Wer die Behauptung als „Unsinn“ abtut, fragt weder nach einem Mechanismus noch nach Testergebnissen und gibt dem Gegenüber keinen Anlass, seine Sicht zu überdenken."},{"option":1,"text":"Eingetroffene Beispiele wirken überzeugend, weil man sich an Treffer gut erinnert. Ohne Vergleich mit dem Zufall sagen sie aber nichts darüber, ob die Treffer mehr als Glück sind. Auch die Fehlschläge fehlen in dieser Frage."},{"option":3,"text":"Ausbildung und Medienauftritte helfen einzuschätzen, wer spricht, aber nicht, ob die Vorhersagen besser als der Zufall sind. Die Frage prüft die Person statt der Behauptung."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? (Nachdruck auf astrology-and-science.com)","oeffentlich":true,"url":"https://astrology-and-science.com/D-psia1.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? Journal of Consciousness Studies 10(6–7), 175–198","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-025","clusterId":"A","werkstueckRef":"A.18","stufe":3,"question":"Jemand sagt: „Es gibt keine absolute Gewissheit, also ist die Kugelgestalt der Erde ebenso gut begründet wie die Scheibe.“ Was ist an diesem Schluss fehlerhaft?","options":["Er fordert zu Recht Belege für beide Seiten, wendet diese Forderung aber nur auf die Kugelgestalt an.","Er behandelt Quellen und Motive der Wissenschaft pauschal als verdächtig, statt Belege zu prüfen.","Er folgert aus fehlender absoluter Gewissheit, dass alle Behauptungen gleich gut belegt sind.","Er verlässt sich auf eine einzelne Autorität, statt die Behauptung selbst zu prüfen."],"correctIndex":2,"explanation":"Dass es keine absolute Gewissheit gibt, stimmt, aber daraus folgt nicht, dass alle Behauptungen gleich unsicher wären. Es gibt verlässliche Methoden, um gut begründetes, wenn auch vorläufiges Wissen zu gewinnen, und die Stärke einer Überzeugung sollte der Stärke der Belege entsprechen. Für die Kugelgestalt der Erde sprechen unabhängige Belege aus vielen Richtungen, etwa Satellitenbilder, Erdumrundungen und der runde Erdschatten bei Mondfinsternissen; für die Scheibe gibt es nichts Vergleichbares. Beide gleichzusetzen ist kein Skeptizismus, sondern gibt das Prüfen auf: Hier kippt der Zweifel in die Haltung, dass gar kein Wissen möglich sei. Ein echter Skeptiker fragt, welche Belege jeweils vorliegen, und stuft sein Vertrauen danach ab.","coreRule":"⚡ Skeptizismus misst Überzeugung an der Stärke der Belege; Gleichmacherei ist keiner.","beleg":"Werkstück A.18 (Der Kipppunkt; Kontext & Tiefe: Proportionalität)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Dass es keine absolute Gewissheit gibt, stimmt, macht aber nicht alle Behauptungen gleich unsicher: Entscheidend ist die Stärke der Belege, und die ist bei der Kugelgestalt ungleich größer. Wer alles gleichsetzt, ist nicht skeptisch, sondern gibt das Prüfen auf.","prueffrage":"Welche Belege lassen sich für jede der beiden Behauptungen tatsächlich nennen, und wie viele sind es?","rueckmeldung":[{"option":0,"text":"Belege von beiden Seiten zu verlangen, ist grundsätzlich fair. Im Satz steht aber keine einseitige Forderung: Er stellt beide Behauptungen gleich, weil nichts absolut gewiss sei. Der Fehler liegt in diesem Schluss, nicht in einem Doppelstandard."},{"option":1,"text":"Quellen und Motive kritisch anzusehen, gehört zum guten Prüfen, und manchmal wird es übertrieben. Der Satz greift aber weder Quellen noch Motive an, sondern schließt allein aus fehlender absoluter Gewissheit auf Gleichwertigkeit."},{"option":3,"text":"Selbst zu prüfen, statt einer einzelnen Autorität zu folgen, ist ein guter Grundsatz. Hier beruft sich der Sprecher aber auf keine Autorität, sondern auf ein allgemeines Prinzip, das er zu weit treibt."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hume, D.: An Enquiry Concerning Human Understanding, Sect. X „Of Miracles“, Part I (Project Gutenberg, Ausg. Selby-Bigge)","oeffentlich":true,"url":"https://www.gutenberg.org/files/9662/9662-h/9662-h.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-026","clusterId":"A","werkstueckRef":"A.18","stufe":4,"question":"Warum ist das Vorgehen von Prüfer B das methodisch bessere?","options":["Prüfer B legt die Regeln vorab fest; so kann der Test eine echte Fähigkeit belegen oder die Behauptung scheitern lassen, ohne dass das Ergebnis nachträglich zurechtgebogen wird.","Prüferin A geht gründlicher vor, weil sie den Betrug sicher aufdeckt; so werden die Leute besser geschützt als durch einen Test mit offenem Ausgang.","Prüfer B schafft am schnellsten Klarheit, weil ein einziger Test die Frage endgültig klärt; so bleibt keine Unsicherheit für spätere Zweifel zurück.","Prüferin A irrt, weil man einer Behauptung ohne Gegenbeweis glauben muss; solange niemand den Trick nachweist, gilt die Behauptung als wahr."],"correctIndex":0,"explanation":"Wer von vornherein weiß, dass jemand betrügt, und dann nur nach dem Trick sucht, kann nichts anderes finden als eine Bestätigung seiner Annahme. Das mag als Entlarvung brillant sein, ist aber keine Untersuchung, denn die Schlussfolgerung stand schon fest. Ein vorab vereinbarter, fairer Test ist ergebnisoffen: Besteht der Prüfling unter kontrollierten Bedingungen, muss man die eigene Meinung ändern; besteht er nicht, bleibt die Behauptung unbewiesen, und kein Prüfer hat sich sein Urteil nachträglich zurechtgelegt. So arbeitete auch der Zauberkünstler James Randi, dessen Millionen-Dollar-Herausforderung nach diesem Prinzip aufgebaut war und bis zu ihrem Ende 2015 von niemandem bestanden wurde. Wichtig: Ein fehlender Gegenbeweis ist kein Beweis für die Behauptung.","coreRule":"⚡ Echte Skepsis lässt dem Behauptenden eine faire Chance, sich zu bewähren.","beleg":"Werkstück A.18 (Einstiegsgeschichte); Fn. ga-randi (Houdini † 1926, Randi * 1928; Zuspitzung, keine wörtlich belegte Aussage)","status":"entwurf","scenario":"Ein Mann behauptet, er könne mit einer Wünschelrute Wasseradern unter der Erde aufspüren. Zwei Prüfer sollen die Behauptung untersuchen. Prüferin A sagt: „Das ist Schwindel. Ich beobachte ihn, bis ich den Trick finde, mit dem er die Leute täuscht.“ Prüfer B sagt: „Wir legen vorab gemeinsam fest, was als Erfolg zählt, schließen Tricks aus und testen ihn unter diesen Bedingungen.“","kurz":"Wer schon weiß, dass jemand betrügt, sucht nur nach Bestätigung, und das Urteil steht vorab fest. Ein vorab vereinbarter, fairer Test kann dagegen in beide Richtungen ausgehen und zwingt dazu, die eigene Meinung notfalls zu ändern.","prueffrage":"Was genau soll der Mann bei Prüfer B tun, und woran liest man danach ab, ob er Erfolg hatte?","rueckmeldung":[{"option":1,"text":"Schutz vor Betrug ist ein berechtigtes Anliegen. Prüferin A sucht aber nur, bis sie ihre Annahme bestätigt findet; dass der Mann die Fähigkeit hat, kann bei ihr nie herauskommen. Das ist keine ergebnisoffene Untersuchung."},{"option":2,"text":"Ein fairer Test ist ergebnisoffen, das macht ihn stark, aber nicht endgültig. Besteht der Mann ihn nicht, bleibt die Behauptung unbewiesen, und ein bestandener Test müsste sich erst wiederholen lassen, bevor er als gesichert gilt."},{"option":3,"text":"Ein fehlender Gegenbeweis ist kein Beweis: Wer etwas behauptet, muss es belegen, und ein nicht gefundener Trick macht die Fähigkeit nicht wahr. Der Fehler von A liegt woanders: Ihr Urteil steht schon vor der Prüfung fest."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: One Million Dollar Paranormal Challenge","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/One_Million_Dollar_Paranormal_Challenge","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-027","clusterId":"A","werkstueckRef":"A.19","stufe":1,"question":"Bevor du am Abend deinem Bauchgefühl folgst: Welche Frage hilft dir am meisten zu beurteilen, ob es für diese Entscheidung verlässlich ist?","options":["Wie sicher fühle ich mich gerade, und wie gut kenne ich dieses Gefühl aus früheren Entscheidungen?","Wie schnell kann ich eine Entscheidung treffen, ohne dass ich mich später darüber ärgern muss?","Wie hoch sind die Kosten eines Irrtums, und ist das ein Bereich, in dem sich mein Bauchgefühl bewährt hat?","Wie viele andere Menschen würden jetzt wahrscheinlich dieselbe Entscheidung treffen wie ich?"],"correctIndex":2,"explanation":"Schnelle Faustregeln wie das Bauchgefühl sind nützlich, wenn ein Fehler wenig kostet: Wer bei Marmelade danebengreift, verliert kaum etwas. Bei einer Wahl oder einer Behandlung kann ein Irrtum dagegen schwere Folgen haben; je mehr auf dem Spiel steht, desto weniger sollte man sich ungeprüft auf eine Faustregel verlassen. Weder ein starkes Gefühl der Sicherheit noch die Zahl der Menschen, die genauso entscheiden würden, zeigt, ob das Bauchgefühl richtigliegt. Deshalb prüfst du zuerst, was auf dem Spiel steht und ob sich dein Bauchgefühl in diesem Bereich schon bewährt hat. Ist der Einsatz hoch und fehlt diese Bewährung, lohnt sich eine langsamere, gründlichere Prüfung anhand von Daten und Alternativen.","coreRule":"⚡ Faustregeln sind meist gut genug, aber je höher die Kosten eines Fehlers, desto eher lohnt die langsame Prüfung.","quote":"Der Kipppunkt ist die Relevanz der Entscheidung.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück A.19 (Kernidee; Kontext & Tiefe); Fn. ga-heuristiken (Tversky/Kahneman 1974, Science 185, S. 1124)","status":"entwurf","scenario":"Zwei Situationen am selben Tag: Im Supermarkt greifst du ohne Nachdenken zur Marmeladensorte, die du kennst. Am Abend soll dein Bauchgefühl entscheiden, ob du einem Kandidaten bei einer wichtigen Wahl deine Stimme gibst oder einer teuren medizinischen Behandlung zustimmst.","kurz":"Entscheidend ist, was ein Irrtum kostet und ob sich dein Bauchgefühl in diesem Bereich schon bewährt hat. Ein starkes Gefühl der Sicherheit oder die Zahl der Menschen, die genauso entscheiden würden, zeigt dagegen nicht, ob es richtigliegt.","prueffrage":"Wie oft hast du bei Marmelade und wie oft bei Wahlen oder Behandlungen schon aus dem Bauch entschieden, und wie ging es aus?","rueckmeldung":[{"option":0,"text":"Frühere Entscheidungen einzubeziehen, wirkt gründlich. Doch wie vertraut und sicher sich ein Gefühl anfühlt, verrät wenig darüber, wie oft es richtiglag, und die Frage, was ein Irrtum kostet, fehlt ganz."},{"option":1,"text":"Bei der Marmelade ist Tempo harmlos, weil ein Fehlgriff kaum etwas kostet. Die Frage nach dem schnellsten Weg ohne späteren Ärger sagt aber nichts darüber, ob dein Bauchgefühl bei einer Wahl oder Behandlung verlässlich ist."},{"option":3,"text":"Was viele andere tun, wirkt wie ein Hinweis auf eine gute Wahl. Entscheiden viele aus dem Bauch, wird der Bauch dadurch aber nicht verlässlicher. Es kommt darauf an, was ein Irrtum kostet und ob sich das Bauchgefühl hier bewährt hat."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"1124"}],"thema":"Psychologie"},{"id":"qx-a2-028","clusterId":"A","werkstueckRef":"A.19","stufe":2,"question":"Warum ist es hier vernünftig, einfach die bekannte Marke zu nehmen, statt alle Sorten zu vergleichen?","scenario":"Im Supermarkt stehst du vor einem Regal mit 50 Marmeladensorten und greifst ohne langes Nachdenken zu deiner gewohnten Marke.","options":["Wer genug Erfahrung hat, trifft mit Faustregeln immer die objektiv beste Wahl, deshalb lohnt sich ein Vergleich nie.","Ein Fehlgriff kostet wenig, ein Vergleich aller Sorten dagegen unverhältnismäßig viel Zeit und Mühe.","Beim Einkaufen schaltet das analytische Denken grundsätzlich ab, deshalb bleibt nur die Faustregel übrig.","Die Vertrautheit mit einer Marke ist eine Faustregel, die niemals zu Fehlurteilen führt, deshalb eignet sie sich für Alltagskäufe."],"correctIndex":1,"explanation":"Faustregeln sind mentale Abkürzungen, die in den meisten Fällen „gut genug“ sind, aber nicht optimal und nicht fehlerfrei. Entscheidend ist das Verhältnis von Aufwand und Einsatz: Bei der Marmelade ist ein möglicher Fehler trivial, während ein vollständiger Vergleich aller 50 Sorten viel Zeit und Energie kostet. Wer vor jedem Regal alles durchrechnen wollte, käme im Alltag kaum zum Handeln. Anders sieht es aus, wenn viel auf dem Spiel steht, etwa bei einer medizinischen Entscheidung: Dort lohnt sich der Wechsel zum langsamen, genauen Prüfen, weil ein Fehler teuer wäre.","coreRule":"⚡ Bei geringem Einsatz ist die Faustregel klug, bei hohem Einsatz lohnt das genaue Rechnen.","beleg":"Werkstück A.19 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Hier ist ein Fehlgriff harmlos, ein Vergleich aller 50 Sorten dagegen aufwendig. Die Faustregel genügt also, weil ein Fehler wenig kostet, nicht weil sie nie danebenläge oder Denken beim Einkaufen abschaltet.","prueffrage":"Wie oft hat dich die gewohnte Marke schon enttäuscht, und was hast du dann getan?","rueckmeldung":[{"option":0,"text":"Mit Erfahrung werden Faustregeln oft treffsicher, aber „immer“ und „objektiv beste Wahl“ gehen zu weit: Sie sind nur meist gut genug. Und bei viel Einsatz lohnt sich genaues Prüfen durchaus."},{"option":2,"text":"Es wirkt, als liefe beim Einkaufen alles automatisch ab. Das analytische Denken bleibt aber jederzeit verfügbar und wird bei hohem Einsatz zugeschaltet. Die Faustregel gilt hier, weil Prüfen sich nicht lohnt, nicht weil Denken ausfiele."},{"option":3,"text":"Vertrautheit ist tatsächlich eine Faustregel, die sich für Alltagskäufe eignet. „Niemals“ trägt aber nicht: Auch sie führt manchmal daneben. Sie genügt, weil ein solcher Fehler wenig kostet."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality (überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"483","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-a2-029","clusterId":"A","werkstueckRef":"A.19","stufe":3,"question":"Woran lässt sich am besten erkennen, dass die Kollegin hier nicht auf die schnelle Faustregel vertrauen sollte?","options":["Sie fühlt sich absolut sicher, also ist die schnelle Faustregel in diesem Fall besonders verlässlich.","Der Einsatz ist hoch und eine Prüfung wäre möglich, also sollte sie in die langsame, datenbasierte Analyse wechseln.","Ein Bauchgefühl entsteht aus eigener Erfahrung, also ist es verlässlicher als jede Zahl oder Gegenprüfung.","Fünf Minuten sind für so einen Vertrag zu kurz, also wäre er nach einer Stunde Grübeln automatisch gut geprüft."],"correctIndex":1,"explanation":"Faustregeln sind schnell und meist gut genug, aber ihre Fehler sind vorhersagbar. Ob du ihnen trauen darfst, hängt davon ab, was ein Fehler kostet: Beim Marmeladenkauf ist er trivial, bei einem mehrjährigen Vertrag oder einer medizinischen Entscheidung kann er schwer wiegen. Dann lohnt sich der Wechsel ins langsame, analytische Denken, zumal Zeit zum Prüfen da ist. Ein starkes Sicherheitsgefühl spricht nicht für die Faustregel: Gerade wer bei einer schnellen Entscheidung in komplexer Lage absolut sicher ist, sollte misstrauisch werden. Und es kommt nicht auf die Dauer des Grübelns an, sondern auf die Art der Prüfung: Daten, Vergleiche, Gegenfragen.","coreRule":"⚡ Je höher der Einsatz, desto weniger darfst du dich auf die schnelle Faustregel verlassen.","beleg":"Werkstück A.19 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Eine Kollegin will in fünf Minuten über einen Vertrag entscheiden, der die Firma mehrere Jahre bindet. Sie sagt: „Ich habe sofort ein gutes Gefühl dabei, das passt. Ich bin mir absolut sicher.“ Detailprüfung oder Vergleichsangebote gab es nicht.","quote":"","quoteLabel":"","kurz":"Hoher Einsatz und vorhandene Zeit zum Prüfen sprechen für die langsame Analyse: Faustregeln sind meist gut genug, aber ihre vorhersagbaren Fehler können bei einem mehrjährigen Vertrag teuer werden. Das Gefühl absoluter Sicherheit ersetzt die Prüfung nicht.","prueffrage":"Was weiß die Kollegin über diesen Vertrag tatsächlich, außer dass er sich nach fünf Minuten gut anfühlt?","rueckmeldung":[{"option":0,"text":"Das Gefühl ist echt, und Faustregeln sind meist gut genug. Starke Sicherheit verbürgt aber keine gute Entscheidung; bei einer schnellen Wahl in komplexer Lage ist sie eher ein Grund zum Misstrauen."},{"option":2,"text":"Bauchgefühle speisen sich tatsächlich oft aus Erfahrung und treffen meist gut. Das macht sie aber nicht verlässlicher als jede Gegenprüfung: Ihre Fehler sind vorhersagbar, und bei hohem Einsatz lohnen sich Daten und Vergleiche."},{"option":3,"text":"Fünf Minuten wirken für diesen Vertrag zwar knapp. Doch eine Stunde Grübeln ändert nichts, wenn nur dieselben Gedanken kreisen. Entscheidend ist die Art der Prüfung: Daten, Vergleiche, Gegenfragen."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465, 472","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-a2-030","clusterId":"A","werkstueckRef":"A.19","stufe":4,"question":"Welcher Denkfehler steckt im Argument des Freundes?","options":["Er nimmt an, die erste Erklärung, die er gehört hat, sei die richtige, und passt seine Einschätzung nur geringfügig an.","Er hält die Verschwörungserklärung für häufig, weil ihm viele Fälle von geheimen Plänen leicht einfallen.","Er hält die Erklärung für glaubwürdig, weil sie ihm aus früheren Gesprächen und Berichten schon vertraut vorkommt.","Er schließt von der Größe des Ereignisses auf eine ebenso große, geordnete Ursache, ohne diese zu prüfen."],"correctIndex":3,"explanation":"Der Freund verlässt sich auf eine Faustregel: Ein großes Ereignis muss auch eine ebenso große Ursache haben. Geplant war der Anschlag zwar, aber von al-Qaida mit 19 Attentätern und nicht von allmächtigen Hintermännern im Verborgenen. Die gewaltigen Folgen sagen also wenig darüber, wie groß und mächtig die Urheber sind; das Gefühl, eine riesige Wirkung verlange eine riesige Ursache, ersetzt keine Prüfung an Belegen. Die anderen Antworten beschreiben andere Denkfehler (Anker, leichte Erinnerbarkeit, Vertrautheit), die im Argument gar nicht vorkommen: Der Freund beruft sich weder auf eine zuerst gehörte Erklärung noch auf erinnerte Einzelfälle noch auf Bekanntes, sondern allein auf die Größe des Ereignisses.","coreRule":"⚡ Wenn eine Erklärung überzeugt, weil sie so groß ist wie das Ereignis, frage nach Belegen statt nach Stimmigkeit.","beleg":"Werkstück A.19 (Anwendung: Bei Verschwörungsmythen; Kontext & Tiefe: Repräsentativitätsheuristik)","status":"entwurf","scenario":"Nach dem Anschlag vom 11. September 2001 verbreitet sich die Behauptung, dahinter müsse ein langfristig geplanter, geheimer Plan mächtiger Hintermänner stecken. Ein Freund sagt: „So etwas Riesiges kann doch unmöglich einfach so passiert sein.“","kurz":"Der Freund schließt von der Größe des Ereignisses auf eine ebenso große, geordnete Ursache. Das fühlt sich stimmig an, ersetzt aber keine Prüfung an Belegen: Riesige Folgen beweisen keine mächtigen Hintermänner.","prueffrage":"Was müsste man über die Täter eines Anschlags wissen, um zu beurteilen, wie mächtig und gut organisiert sie waren?","rueckmeldung":[{"option":0,"text":"Sich an eine zuerst gehörte Erklärung zu klammern, ist ein bekannter Fehler. Davon ist hier aber nichts zu sehen: Der Freund beruft sich nicht darauf, was er zuerst gehört hat, sondern auf die schiere Größe des Ereignisses."},{"option":1,"text":"Dass uns auffällige Einzelfälle leicht einfallen und deshalb häufiger wirken, ist ein echter Denkfehler. Der Freund nennt aber keine Einzelfälle und schätzt keine Häufigkeit; sein ganzer Gedanke hängt an der Größe des Ereignisses."},{"option":2,"text":"Vertraut Klingendes wirkt oft glaubwürdiger, das ist ein bekannter Effekt. Der Freund begründet seine Haltung aber nicht damit, dass er die Geschichte schon kennt, sondern damit, dass etwas so Großes nicht zufällig geschehen könne."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brotherton, R.; French, C. C. (2014): Belief in Conspiracy Theories and Susceptibility to the Conjunction Fallacy. Applied Cognitive Psychology 28, 238–248 (Repositorium Goldsmiths)","oeffentlich":true,"url":"https://eprints-gro.gold.ac.uk/10794/1/acp2995.pdf","seite":"238","abruf":"2026-10-12"},{"typ":"url","kurz":"National Commission on Terrorist Attacks Upon the United States: The 9/11 Commission Report, Executive Summary","oeffentlich":true,"url":"https://www.9-11commission.gov/report/911Report_Exec.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-031","clusterId":"A","werkstueckRef":"A.20","stufe":1,"question":"Welche Antwort erklärt am besten, warum die Ärzte damals Semmelweis’ Idee nicht prüften, sondern als „sinnlosen Lärm“ abtaten?","options":["Die Idee passte nicht in den unausgesprochenen Rahmen aus Annahmen, den alle für selbstverständlich hielten, und galt deshalb gar nicht erst als ernsthafte Hypothese.","Die Ärzte hatten die Idee im Experiment geprüft und verworfen, weil die Sterblichkeit trotz Händewaschen unverändert hoch blieb.","Die Ärzte hatten als Gruppe festgelegt, wie Hypothesen zu prüfen sind, und Semmelweis hatte dieses Verfahren nicht eingehalten.","Die Ärzte wollten die Idee prüfen, hatten aber kein Mittel, sie durch einen einzelnen Versuch zu bestätigen oder zu widerlegen."],"correctIndex":0,"explanation":"Die Ablehnung lässt sich am sparsamsten so erklären: Ein System selbstverständlicher Annahmen (Krankheit durch Miasmen oder Säfteungleichgewicht) bestimmt, was überhaupt als sinnvolle Idee zählt. Innerhalb dieses Rahmens war „Leichenteilchen an den Händen“ keine falsche Hypothese, sondern unverständlich. Solche Rahmen sind meist unbewusst, die Beteiligten halten sie schlicht für „normal“. Das erklärt auch, warum Fakten allein den Streit nicht entschieden: Erst Jahrzehnte später, mit Pasteurs Keimtheorie, wurde Semmelweis’ Idee bestätigt. Ganz unschuldig war Semmelweis allerdings nicht: Er veröffentlichte spät, konnte die Wirkung des Chlorkalks nicht erklären und beschimpfte Kritiker. Die übrigen Erklärungen passen nicht zum Hergang: Eine gründliche Prüfung, ein verletztes Verfahren oder ein fehlendes Testmittel würden voraussetzen, dass die Idee überhaupt als prüfbare Hypothese galt. Hier ging es um etwas Grundsätzlicheres als eine einzelne Methode oder einen einzelnen Test.","coreRule":"⚡ Ein Paradigma ist die unsichtbare Karte, nach der ein Fach navigiert: Es entscheidet mit, was als sinnvolle Idee gilt, noch bevor jemand prüft.","beleg":"Werkstück A.20 (Kernidee; Kontext & Tiefe); Fn. ga-kuhn (Kuhn 1962, The Structure of Scientific Revolutions)","status":"entwurf","scenario":"Wien, 1847: Viele Wöchnerinnen sterben am Kindbettfieber. Ein junger Arzt behauptet, unsichtbare Leichenteilchen an den Händen der Ärzte seien die Ursache, und verlangt, dass sich alle vor jeder Untersuchung die Hände in Chlorkalklösung waschen. Seine Kollegen halten das für absurd und beleidigend. Dabei sind sie weder dumm noch unehrlich, sondern erfahrene Ärzte, die sich an dem orientieren, was zu ihrer Zeit als gesichertes Wissen gilt: Krankheiten entstehen durch schlechte Luft (Miasmen) oder ein Ungleichgewicht der Körpersäfte.","quote":"","quoteLabel":"","kurz":"Im Rahmen aus Miasmen und Säfteungleichgewicht war „Leichenteilchen an den Händen“ keine falsche Hypothese, sondern unverständlich, und wurde gar nicht erst geprüft. Wer die Ablehnung mit Prüfung oder Verfahren erklärt, setzt voraus, dass die Idee als prüfbar galt.","prueffrage":"Wofür hielten die Kollegen die Forderung, und wie würdest du reagieren, wenn du nur ihr damaliges Wissen hättest?","rueckmeldung":[{"option":1,"text":"Eine gescheiterte Prüfung würde die Ablehnung gut erklären. Doch die Ärzte prüften die Idee nicht, sie taten sie als „sinnlosen Lärm“ ab; es gab also kein Ergebnis, das sie widerlegt hätte."},{"option":2,"text":"Ein vereinbartes Prüfverfahren, gegen das Semmelweis verstoßen hätte, würde eine Ablehnung begründen, doch davon ist nirgends die Rede. Auch seine späte Veröffentlichung erklärt nicht, warum die Idee schon vor jeder Prüfung als unverständlich galt."},{"option":3,"text":"Dass ein einzelner Versuch selten eine Hypothese endgültig klärt, stimmt. Von fehlenden Mitteln ist aber keine Rede: Die Ärzte hielten die Idee für absurd und beleidigend und prüften sie gar nicht erst."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Best, M.; Neuhauser, D. (2004): Ignaz Semmelweis and the birth of infection control. Quality & Safety in Health Care 13(3), 233–234","oeffentlich":true,"doi":"10.1136/qshc.2004.010918","seite":"233–234","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schreiner, S. (2020): Ignaz Semmelweis: a victim of harassment? Wiener Medizinische Wochenschrift 170(11–12), 293–302","oeffentlich":true,"doi":"10.1007/s10354-020-00738-1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-033","clusterId":"A","werkstueckRef":"A.20","stufe":3,"question":"Wie ist das Verhalten dieser Fachgesellschaft zu beurteilen, und welcher Schritt wäre sinnvoll?","options":["Das Verhalten ist problematisch, weil Abweichungen ohne Prüfung wegerklärt und die Kritikerin ausgegrenzt werden. Sinnvoll wäre, die Daten unabhängig nachzuprüfen.","Das Verhalten ist unproblematisch, weil die Theorie im Alltag gut funktioniert und die Mehrheit der Mitglieder sie teilt. Sinnvoll wäre, bei dieser Linie zu bleiben.","Das Verhalten ist problematisch, weil die Fachgesellschaft überhaupt an einer Theorie festhält. Sinnvoll wäre, die Theorie sofort durch die Außenseiterposition zu ersetzen.","Das Verhalten ist unproblematisch, weil einzelne abweichende Messwerte nie etwas bedeuten. Sinnvoll wäre, weitere Abweichungen von vornherein auszusortieren."],"correctIndex":0,"explanation":"Ein gemeinsamer Theorierahmen ist nützlich: Er erspart es, bei jeder Beobachtung die Grundlagen neu zu verhandeln, und macht die Arbeit an Detailproblemen effizient. Dass die Theorie meist funktioniert und von vielen geteilt wird, spricht also nicht gegen sie, aber auch nicht gegen die Prüfung von Abweichungen. Problematisch wird ein Rahmen, wenn Abweichungen nicht mehr untersucht, sondern ungeprüft wegerklärt und Kritiker nicht mehr als Herausforderer, sondern als Feinde behandelt werden: Dann erstarrt er zum Dogma. Genau das passiert hier: Die Daten werden ungeprüft abgetan, die Forscherin wird ausgegrenzt. Sinnvoll ist deshalb, die Daten unabhängig nachzuprüfen; ob die Theorie angepasst oder gar ersetzt werden muss, zeigt erst diese Prüfung.","coreRule":"⚡ Ein Rahmen wird zum Dogma, wenn er Abweichungen und Kritiker bekämpft, statt sie zu untersuchen.","beleg":"Werkstück A.20 (Der Kipppunkt; Das Adaptive Talent; Kontext & Tiefe; Einleitung zu Semmelweis)","status":"entwurf","scenario":"In einer Fachgesellschaft häufen sich seit Jahren Messergebnisse, die zur herrschenden Theorie nicht passen. Der Vorstand erklärt sie regelmäßig zu Messfehlern, ohne die Daten nachzuprüfen. Eine Forscherin, die die Abweichungen systematisch untersuchen will, gilt als Querulantin; ihre Beiträge werden nicht mehr zu Tagungen eingeladen. Im Alltag funktioniert die Theorie sonst gut, und die meisten Mitglieder arbeiten gern damit.","kurz":"Ein gemeinsamer Rahmen ist nützlich, wird aber zum Problem, wenn sich häufende Abweichungen ungeprüft wegerklärt und Kritiker als Feinde behandelt werden. Unabhängiges Nachprüfen der Daten nimmt die Abweichungen ernst, ohne die Theorie gleich zu verwerfen.","prueffrage":"Wie lange häufen sich die Abweichungen schon, und was ist mit der Forscherin geschehen, die sie untersuchen wollte?","rueckmeldung":[{"option":1,"text":"Dass die Theorie im Alltag gut funktioniert und viele sie teilen, ist ein echter Vorzug und spricht nicht gegen sie. Es ist aber kein Grund, sich häufende Abweichungen ungeprüft abzutun und die Forscherin auszugrenzen."},{"option":2,"text":"Hier ist das Verhalten tatsächlich problematisch, aber der Grund sitzt woanders. An einer Theorie festzuhalten ist an sich nützlich; kritisch wird es erst, wenn Abweichungen nicht untersucht werden. Dafür muss die Theorie nicht sofort ersetzt werden."},{"option":3,"text":"Ein einzelner Messwert kann tatsächlich ein Fehler sein, doch das lässt sich erst nach einer Prüfung sagen. Hier häufen sich die Abweichungen seit Jahren; sie von vornherein auszusortieren, hieße, das ungeprüfte Wegerklären fortzusetzen."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-034","clusterId":"A","werkstueckRef":"A.20","stufe":4,"question":"Ein Anbieter wirbt für sein „neues Paradigma“ und sagt: „Wer zweifelt, ist noch im alten Denken gefangen.“ Wie bewertest du das?","options":["Als Warnzeichen: Eine Neuerung überzeugt durch bessere Erklärungen; der Satz macht den Anspruch gegen Kritik unangreifbar.","Als berechtigten Hinweis: Wer in einem Denkrahmen steckt, kann einen grundlegend neuen Rahmen prinzipiell nie verstehen und sich nicht überzeugen lassen.","Als überzeugend: Es genügt, wenn der Anbieter einige Probleme des alten Modells benennt, die dieses nicht erklären kann.","Als unerheblich: Jede grundlegend neue Idee wird zunächst nur von wenigen vertreten und von der Mehrheit abgelehnt."],"correctIndex":0,"explanation":"Wer Zweifel als Zeichen von Befangenheit abwertet, macht seine Behauptung unprüfbar: Jeder Einwand wird zum Beweis, dass der Kritiker „es nicht verstanden hat“. Eine echte Neuerung in der Wissenschaft setzt sich anders durch: Sie erklärt Beobachtungen, an denen das Alte scheitert, und leistet dabei fast alles, was das Alte leistete. Selbst dann gehen manchmal einzelne Erklärungen verloren, aber nicht der Großteil des Bewährten. Einige Schwächen des alten Modells zu nennen, reicht nicht: Ein neues Paradigma muss die meisten Anomalien lösen und fast alles bewahren, was das alte leistete. Dass Neues anfangs wenige überzeugt, ist kein Gütezeichen: Auch Semmelweis’ Idee setzte sich erst später durch, als sie erklärt werden konnte. Entscheidend ist, ob eine Neuerung mehr erklärt und prüfbar ist.","coreRule":"⚡ Eine Neuerung überzeugt durch bessere Erklärungen, nicht dadurch, Kritik zu entwerten.","beleg":"Werkstück A.20 (Anwendung: Bei Pseudowissenschaften & Esoterik; Red Flags: „Kritik wird als Beweis dafür abgetan, dass der Kritiker noch im alten Paradigma gefangen ist“); Fn. ga-kuhn (Kuhn 1962; Bird, SEP „Thomas Kuhn“, Abschn. 2: Kuhn-loss)","status":"entwurf","kurz":"Der Satz macht jeden Einwand zum Beweis, dass der Kritiker „es nicht verstanden hat“, und entzieht die Behauptung damit der Prüfung. Eine echte Neuerung überzeugt dagegen, weil sie Beobachtungen erklärt, an denen das Alte scheitert, und das Bewährte weitgehend bewahrt.","prueffrage":"Was erfährt man aus dem Satz des Anbieters über sein Produkt selbst, und was nur über die Zweifler?","rueckmeldung":[{"option":1,"text":"Dass ein vertrauter Denkrahmen das Verstehen erschweren kann, stimmt. „Nie“ geht aber zu weit: Neuerungen überzeugen gerade, indem sie erklären, woran das Alte scheitert, und der Satz des Anbieters entzieht sich jeder solchen Prüfung."},{"option":2,"text":"Schwächen des alten Modells zu zeigen, gehört zu jeder Neuerung dazu, genügt aber nicht. Ein neues Paradigma muss die meisten dieser Probleme lösen und fast alles bewahren, was das alte leistete, sonst ersetzt es nur eine Lücke durch eine andere."},{"option":3,"text":"Neue Ideen haben es anfangs oft schwer, Semmelweis ist ein Beispiel. Ablehnung durch die Mehrheit ist aber kein Gütezeichen: Entscheidend ist, ob die Neuerung mehr erklärt und prüfbar ist, und genau diese Prüfung verbaut der Satz."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-035","clusterId":"A","werkstueckRef":"A.21","stufe":1,"question":"Du bekommst eine Wette angeboten: Münzwurf, bei Kopf gewinnst du 150 Euro, bei Zahl verlierst du 100 Euro. Du lehnst ab, obwohl du bei vielen Wiederholungen im Schnitt Geld gewinnen würdest. Wie lässt sich deine Ablehnung am besten erklären?","options":["Du hast dich verrechnet: Der Durchschnittswert der Wette ist in Wahrheit null, deshalb ist deine Ablehnung rein rational begründet.","Menschen sind bei möglichen Gewinnen grundsätzlich risikofreudig und suchen deshalb stets die Wette mit dem höchsten möglichen Ertrag.","Dein bisheriger Besitz spielt für die Entscheidung keine Rolle, denn allein der absolute Endbestand bestimmt, wie du die Wette bewertest.","Ein möglicher Verlust von 100 Euro wiegt psychologisch schwerer als die Aussicht auf einen Gewinn von 150 Euro, obwohl der Durchschnitt positiv ist."],"correctIndex":3,"explanation":"Der Durchschnittswert der Wette liegt bei +25 Euro (0,5 × 150 − 0,5 × 100); die Behauptung, er sei null oder negativ, rechnet also falsch. Trotzdem lehnen die meisten Menschen ab, weil ein möglicher Verlust von 100 Euro stärker wiegt als ein gleich großer Gewinn. Das ist Verlustaversion, ein Kernstück der Prospect Theory von Kahneman und Tversky: Entschieden wird nicht über absolute Endzustände, sondern über Gewinne und Verluste relativ zu einem Referenzpunkt (dem, was man schon hat). In der Messung von 1992 zählte ein Verlust etwa doppelt so stark wie ein gleich hoher Gewinn. Risikofreude gibt es eher im Bereich der Verluste, nicht der Gewinne.","coreRule":"⚡ Verluste und Gewinne wiegen nicht gleich: Ein Verlust zählt psychologisch etwa doppelt, deshalb lehnen wir auch Wetten mit positivem Durchschnitt ab.","beleg":"Werkstück A.21 (Einstiegsgeschichte; Kernidee); Fn. ga-prospect (Kahneman/Tversky 1979, Econometrica 47(2), S. 279; Tversky/Kahneman 1992, S. 311)","status":"entwurf","scenario":"Eine Freundin schlägt dir vor: „Wir werfen eine faire Münze. Bei Kopf zahle ich dir 150 Euro, bei Zahl zahlst du mir 100 Euro.“ Du merkst, dass du eigentlich keine Lust darauf hast, obwohl du nachrechnest, dass du im Durchschnitt 25 Euro pro Wurf gewinnen würdest.","kurz":"Die Wette bringt im Schnitt +25 Euro, trotzdem lehnen viele ab: Ein möglicher Verlust von 100 Euro wiegt psychologisch schwerer als ein möglicher Gewinn von 150 Euro. Diese Verlustaversion erklärt die Ablehnung, nicht ein Rechenfehler.","prueffrage":"Was ergibt 0,5 × 150 − 0,5 × 100, und reicht dieses Ergebnis, damit du zusagst?","rueckmeldung":[{"option":0,"text":"Wer zögert, vermutet schnell einen Rechenfehler. Die Rechnung stimmt aber: 0,5 × 150 − 0,5 × 100 ergibt +25 Euro. Der Durchschnitt ist positiv, die Ablehnung muss also einen anderen Grund haben."},{"option":1,"text":"Die Aussicht auf 150 Euro lockt tatsächlich. Doch bei möglichen Gewinnen sind Menschen eher vorsichtig als risikofreudig, und deine Ablehnung zeigt gerade, dass hier nicht der höchste Ertrag den Ausschlag gibt, sondern der mögliche Verlust."},{"option":2,"text":"Allein auf den Endbestand zu schauen, wirkt sauber gerechnet. Menschen bewerten Gewinne und Verluste aber von dem aus, was sie schon haben, und erst dieser Bezugspunkt macht den möglichen Verlust von 100 Euro so spürbar."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1992): Advances in Prospect Theory: Cumulative Representation of Uncertainty. Journal of Risk and Uncertainty 5(4), 297–323","oeffentlich":false,"doi":"10.1007/BF00122574","seite":"311"}],"thema":"Geld und Zahlen"},{"id":"qx-a2-036","clusterId":"A","werkstueckRef":"A.21","stufe":2,"question":"Ein Anleger hat zwei Aktien: eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine davon verkaufen und sagt: „Die Gewinneraktie nehme ich mit, die Verliererin behalte ich, die erholt sich schon wieder.“ Welche Erklärung für dieses Verhalten passt zu dem, was die Prospect Theory über Entscheidungen unter Unsicherheit beschreibt?","scenario":"Ein Anleger besitzt zwei Aktien: Die eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine verkaufen und entscheidet sich für die Gewinneraktie. Die Verliereraktie behält er und sagt: „Die erholt sich schon wieder.“","options":["Im Plus lässt er sich auf das Risiko weiterer Kurssprünge ein und lässt den Gewinn laufen, im Minus will er den Verlust sofort begrenzen und trennt sich rasch davon.","Im Plus will er den sicheren Gewinn festhalten, im Minus wagt er lieber das Risiko eines noch größeren Verlusts, um die Chance auf Rückkehr zum Einstandskurs zu wahren.","Im Plus wie im Minus scheut er das Risiko gleichermaßen, deshalb behandelt er beide Aktien nach demselben Muster und verkauft sie in gleicher Weise.","Im Plus entscheidet er nüchtern nach den Zahlen, im Minus dagegen nach Zufall und ohne erkennbares Muster, weil dort keine Regel gilt."],"correctIndex":1,"explanation":"Die Prospect Theory beschreibt ein asymmetrisches Risikoverhalten: Im Bereich der Gewinne bevorzugen Menschen den sicheren, kleineren Gewinn, im Bereich der Verluste nehmen sie lieber ein größeres Risiko in Kauf, um den Verlust vielleicht ganz zu vermeiden. Der Referenzpunkt ist dabei der Einstandskurs. Deshalb werden Gewinne oft zu früh realisiert und Verluste zu lange gehalten. Der Satz „die erholt sich schon wieder“ ist selbst ein Warnzeichen: Er begründet das Festhalten mit der Hoffnung, nicht mit einer Prüfung der Aussichten. Die klärende Frage lautet: „Würde ich diese Aktie heute zu diesem Kurs neu kaufen?“ Wenn nicht, spricht wenig fürs Halten. Wenn ja, ist das Halten begründet, aber dann nicht wegen des Verlusts.","coreRule":"⚡ Gewinne sichern wir zu früh, Verluste halten wir zu lange.","beleg":"Werkstück A.21 (Kontext & Tiefe, Pfeiler 3; Anwendung: finanzielle Entscheidungen); Fn. ga-prospect-gewichtung (Kahneman/Tversky 1979, S. 268–269)","status":"entwurf","kurz":"Im Gewinn nehmen Menschen lieber das Sichere, im Verlust gehen sie eher ein größeres Risiko ein, um den Einstandskurs noch zu erreichen. Daher werden Gewinne oft zu früh realisiert und Verluste zu lange gehalten, und „die erholt sich schon“ ist Hoffnung statt Prüfung.","prueffrage":"Was tut der Anleger mit der Gewinneraktie, was mit der Verliererin, und womit begründet er das Halten?","rueckmeldung":[{"option":0,"text":"Hier ist das Muster vertauscht: Der Anleger verkauft den Gewinner und behält den Verlierer, nicht umgekehrt. Dass die Lage zum Einstandskurs sein Verhalten steuert, stimmt, nur die Richtung ist verkehrt."},{"option":2,"text":"Gleiche Risikoscheu hieße gleiche Behandlung beider Aktien. Er behandelt sie aber verschieden, den Gewinner gibt er her, am Verlierer hält er fest: Seine Risikohaltung wechselt mit Gewinn oder Verlust."},{"option":3,"text":"Zufall steckt hier nicht dahinter: Im Minus folgt er einem erkennbaren Muster, der Hoffnung auf Rückkehr zum Einstandskurs. Auch im Plus richtet er sich nach dem Einstandskurs und sichert den Gewinn; beides ist systematisch."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"url","kurz":"Odean, T.: Are Investors Reluctant to Realize Their Losses? (Autorenseite, UC Berkeley)","oeffentlich":true,"url":"https://faculty.haas.berkeley.edu/odean/papers/disposition/disposition.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen"},{"id":"qx-a2-037","clusterId":"A","werkstueckRef":"A.21","stufe":3,"question":"Was ist an der Aussage des Kollegen fehlerhaft?","scenario":"Eine Beraterin legt einem Kunden zwei Aufgaben vor. Aufgabe 1: Du erhältst zuerst 1.000 € und wählst dann zwischen A) garantiert weiteren 500 € und B) Münzwurf: bei Kopf weitere 1.000 €, bei Zahl nichts. Aufgabe 2: Du erhältst zuerst 2.000 € und wählst dann zwischen C) garantiert 500 € Verlust und D) Münzwurf: bei Kopf 1.000 € Verlust, bei Zahl nichts. In einem Test wählt die Mehrheit bei Aufgabe 1 die sichere Option A und bei Aufgabe 2 den Münzwurf D. Ein Kollege sagt: „Die Leute haben eben zwei unterschiedliche Situationen bewertet, das ist völlig vernünftig.“","options":["Er übersieht, dass A und C beide garantiert 1.500 € bedeuten und B und D beide im Schnitt 1.500 €; nur die Formulierung als Gewinn oder Verlust unterscheidet sich.","Er übersieht, dass bei Aufgabe 2 mehr Geld im Spiel ist und eine Entscheidung dort deshalb grundsätzlich vorsichtiger ausfallen müsste.","Er übersieht, dass Menschen bei Münzwürfen grundsätzlich die riskante Option wählen, egal ob es um Gewinne oder Verluste geht.","Er übersieht, dass die Mehrheit nach dem Nachrechnen immer die Option mit dem höchsten Erwartungswert wählt, auch wenn sie anfangs anders entscheidet."],"correctIndex":0,"explanation":"Rechne die Endzustände durch: Bei A hast du garantiert 1.000 € + 500 € = 1.500 €, bei C garantiert 2.000 € − 500 € = 1.500 €. Bei B ergibt sich je zur Hälfte 2.000 € oder 1.000 €, bei D je zur Hälfte 1.000 € oder 2.000 €, also im Schnitt jeweils 1.500 €. Aufgabe 1 und Aufgabe 2 sind daher in der Sache identisch. Trotzdem wählen die meisten bei der Gewinnrahmung die sichere Option und bei der Verlustrahmung den Münzwurf. Das ist kein vernünftiger Unterschied in der Lage, sondern ein Rahmungseffekt: Wer von einem Referenzpunkt aus in Gewinnen denkt, meidet Risiko; wer in Verlusten denkt, geht es ein, um den sicheren Verlust zu vermeiden. Wäre die Wahl rein vom Endzustand bestimmt, müsste sie in beiden Aufgaben gleich ausfallen.","coreRule":"⚡ Gleiche Fakten, andere Rahmung: Prüfe zuerst die Endzustände. Ändert sich die Entscheidung nur durch die Formulierung als Gewinn oder Verlust, steuert der Referenzpunkt dein Risikoverhalten.","beleg":"Werkstück A.21 (Das Härten im Feuer: Die Schmiede-Übung; Red Flags)","status":"entwurf","kurz":"Rechnet man die Endzustände durch, sind beide Aufgaben identisch: sicher 1.500 € oder im Schnitt 1.500 € per Münzwurf. Der Unterschied liegt nur in der Darstellung als Gewinn oder Verlust, und genau das übersieht, wer von zwei verschiedenen Situationen spricht.","prueffrage":"Mit welchem Betrag gehst du in jeder der vier Varianten nach der Entscheidung nach Hause?","rueckmeldung":[{"option":1,"text":"Dass in Aufgabe 2 der Startbetrag höher ist, stimmt. Am Ende kommt aber in beiden Aufgaben dasselbe heraus: sicher 1.500 € oder je zur Hälfte 1.000 € oder 2.000 €. Der höhere Startbetrag erklärt den Wechsel also nicht."},{"option":2,"text":"Eine feste Vorliebe für den Münzwurf würde in beiden Aufgaben dieselbe Wahl erzeugen. Die Mehrheit wechselt aber, bei Aufgabe 1 zur sicheren Option, bei Aufgabe 2 zum Münzwurf: Die Darstellung als Gewinn oder Verlust steuert die Wahl."},{"option":3,"text":"Hier gibt es gar keine Option mit höherem Erwartungswert, denn alle vier führen im Schnitt zu 1.500 €. Auch von einem Umdenken nach dem Nachrechnen ist keine Rede; der Test zeigt die anfänglichen Entscheidungen der Mehrheit."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–463","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen"},{"id":"qx-a2-038","clusterId":"A","werkstueckRef":"A.21","stufe":4,"question":"Ein Marketingteam schlägt vor, den Slogan „Jetzt kaufen und 20 % sparen!“ durch „Verpass nicht die Chance, 20 % zu sparen!“ zu ersetzen. Begründung: Verluste wiegen psychologisch schwerer als gleich hohe Gewinne, also müsse der Verlust-Frame stärker wirken. Wie sicher darf man sich bei dieser Erwartung sein?","options":["Sehr sicher: Weil Verluste schwerer wiegen als Gewinne, muss jede Verlust-Botschaft stärker überzeugen als die Gewinn-Version.","Gar nicht sicher: Eine Theorie über Entscheidungen unter Risiko sagt über die Wirkung von Werbesätzen grundsätzlich nichts aus.","Eher unsicher: Gewinn- und Verlust-Frames bei Botschaften wurden bisher noch gar nicht systematisch miteinander verglichen.","Mäßig sicher: Die Erwartung ist plausibel, aber Vergleichsstudien zeigen meist nur kleine, uneinheitliche Unterschiede zwischen beiden Frames."],"correctIndex":3,"explanation":"Aus einer gut belegten Theorie über Entscheidungen unter Unsicherheit folgt nicht automatisch, dass ein bestimmter Werbesatz besser verkauft. Zwischen Theorie und Anwendung liegen viele Zwischenschritte: Wie nehmen Menschen die Botschaft wahr, wie viel Aufmerksamkeit schenken sie ihr, welche Alternativen haben sie? Eine Metaanalyse von O'Keefe und Jensen (2007) mit 93 Studien und 21.656 Teilnehmenden zu Botschaften über Krankheitsvorsorge, also nicht zu Werbung, fand sogar einen sehr kleinen Vorteil des Gewinn-Frames (r = 0,03). Das lässt sich nicht direkt auf Kaufverhalten übertragen, zeigt aber, dass Frame-Effekte klein und uneinheitlich sein können. Die Erwartung ist daher eine plausible Hypothese, keine gesicherte Wirkung; ob der Verlust-Frame beim eigenen Publikum wirkt, lässt sich nur messen, etwa mit einem Vergleichstest.","coreRule":"⚡ Was eine Theorie nahelegt, muss sich in der Praxis erst messen lassen.","beleg":"Werkstück A.21 (Anwendung: Im Marketing); Fn. ga-framing-persuasion (O'Keefe/Jensen 2007, Journal of Health Communication 12(7), S. 623–644)","status":"entwurf","scenario":"","kurz":"Aus einer gut belegten Theorie folgt nicht automatisch, dass ein bestimmter Werbesatz besser wirkt. Gewinn- und Verlustformulierungen von Botschaften unterschieden sich in Vergleichsstudien meist nur wenig; die Erwartung ist plausibel, aber eine Hypothese, die man testen muss.","prueffrage":"Was geschieht zwischen dem Lesen des Satzes und dem tatsächlichen Kauf, und wie ließe sich die Wirkung beim eigenen Publikum messen?","rueckmeldung":[{"option":0,"text":"Dass Verluste schwerer wiegen, ist gut belegt, und genau daher kommt die Sicherheit. Aus der Theorie folgt aber nicht, dass jeder Verlust-Satz besser verkauft; in Vergleichsstudien waren die Unterschiede meist klein und uneinheitlich."},{"option":1,"text":"Die Theorie allein sagt tatsächlich nicht vorher, wie ein Satz wirkt. Daraus folgt aber nicht, dass sie nichts aussagt: Sie liefert eine begründete Hypothese, die man prüfen kann."},{"option":2,"text":"Der Vergleich wurde durchaus untersucht, etwa in einer Metaanalyse mit 93 Studien. Die Unsicherheit entsteht nicht durch fehlende Forschung, sondern weil die Unterschiede dort klein und uneinheitlich ausfielen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007): The relative persuasiveness of gain-framed and loss-framed messages for encouraging disease prevention behaviors: a meta-analytic review. Journal of Health Communication 12(7), 623–644 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17934940/","abruf":"2026-10-12"},{"typ":"doi","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007), Verlagsfassung","oeffentlich":false,"doi":"10.1080/10810730701615198"}],"thema":"Netz und Medien"},{"id":"qx-a2-039","clusterId":"A","werkstueckRef":"A.22","stufe":1,"question":"Ein Video-Kommentar zu einer Termitenburg lautet: „So ein Bauwerk mit Belüftungsschächten und Kühlsystem braucht zwingend einen Gesamtplan. Irgendwo muss der gespeichert sein, sonst wäre das reiner Zufall.“ Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Sie setzt voraus, dass komplexe Ordnung einen zentralen Plan braucht. Sie kann aber aus einfachen Regeln und Wechselwirkungen vieler Individuen entstehen, ohne dass irgendwo ein Gesamtplan existiert.","Sie unterschätzt, wie viele Termiten beteiligt sind. Erst ab einer genügend großen Zahl an Tieren entsteht ein Gesamtplan, der dann in der Kolonie gespeichert ist.","Sie übersieht, dass die Königin den Gesamtplan kennt. Er wird über Duftsignale an die Arbeiter weitergegeben und steuert so jeden einzelnen Bauschritt.","Sie ignoriert, dass jede Termite einen kleinen Teil des Plans kennt. Aus der Summe dieser Teilpläne ergibt sich das Bauwerk, sobald genug Tiere zusammenarbeiten."],"correctIndex":0,"explanation":"Der Schluss „komplexes Ergebnis, also muss es einen Plan geben“ ist ein Fehlschluss. Einzelne Tiere folgen simplen Regeln und kennen weder Belüftungsschacht noch Gesamtform. Erst das Zusammenspiel vieler Individuen erzeugt Strukturen auf der höheren Ebene, die man aus der Untersuchung eines einzelnen Tieres nicht vorhersagen könnte. Das nennt man Emergenz. Ein zentraler Plan ist dafür nicht nötig. Auch die Varianten mit Königin oder verteilten Teilplänen schieben den Plan nur an eine andere Stelle, statt zu fragen, ob es ihn überhaupt braucht. Eine sinnvolle Gegenprobe ist die Frage, welche einfachen Regeln und Wechselwirkungen das Ergebnis erzeugen könnten.","coreRule":"⚡ Komplexe Ordnung braucht keinen zentralen Plan: Sie kann aus den Beziehungen einfacher Teile entstehen.","beleg":"Werkstück A.22 (Einstiegsgeschichte; Kernidee)","status":"entwurf","scenario":"Eine Termitenkolonie besteht aus Tausenden Tieren. Jedes folgt nur einfachen Reaktionsregeln, etwa „Lege Material ab, wo schon Material liegt“ oder „Folge dem Duftsignal der Nachbarn“. Beobachtet wird: Das Gesamtbauwerk ist komplex und zweckmäßig, etwa mit Belüftung und Temperaturregelung.","kurz":"Aus einem komplexen Ergebnis folgt nicht, dass irgendwo ein Plan liegen muss. Einfache Regeln vieler Tiere können im Zusammenspiel Belüftung und Kühlung hervorbringen, auch wenn keine Termite die Gesamtform kennt (Emergenz).","prueffrage":"Weiß eine einzelne Termite, wie der fertige Bau aussehen soll, und woran würdest du das erkennen?","rueckmeldung":[{"option":1,"text":"Dass sehr viele Tiere beteiligt sind, stimmt, und das ist tatsächlich wichtig. Die Menge erzeugt aber keinen Plan, der irgendwo liegt. Entscheidend ist, wie die einfachen Regeln der Tiere ineinandergreifen."},{"option":2,"text":"Eine Königin als Planträgerin würde den Plan nur an eine andere Stelle verlegen. Die Duftsignale wirken unter Nachbarn als einfache Reaktionsregel, nicht als Weitergabe eines Bauplans."},{"option":3,"text":"Teilpläne wirken wie ein Mittelweg, bleiben aber beim Planen. Einfache Reaktionsregeln sind keine Stücke eines Bauplans: Die Tiere kennen weder Schacht noch Gesamtform. Die Ordnung entsteht erst im Zusammenspiel."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Calovi, D. S. u. a. (2019): Surface curvature guides early construction activity in mound-building termites. Phil. Trans. R. Soc. B 374","oeffentlich":true,"doi":"10.1098/rstb.2018.0374","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-a2-040","clusterId":"A","werkstueckRef":"A.22","stufe":2,"question":"Ein Redner sagt: „Wasser ist nass, obwohl weder Wasserstoff noch Sauerstoff nass sind. Das beweist, dass man nichts verstehen kann, wenn man nur die Einzelteile untersucht.“ Wo liegt der Fehler in dieser Schlussfolgerung?","options":["Er übersieht, dass Nässe nur im Zusammenspiel vieler Moleküle auftritt und die Beobachtung deshalb gar keine Aussage über Einzelteile begründen kann.","Er geht zu weit: Dass sich eine Eigenschaft nicht aus den Einzelteilen allein ablesen lässt, heißt nicht, dass die Einzelteile unwichtig sind.","Er verwechselt Nässe mit Flüssigkeit, denn jede Flüssigkeit macht Dinge nass, und das lässt sich aus dem Verhalten der Atome erklären.","Er unterschätzt, dass sich Eigenschaften wie Nässe mit genügend Rechenleistung exakt aus einem einzelnen Molekül vorhersagen lassen."],"correctIndex":1,"explanation":"Die Beobachtung stimmt: Wasserstoff ist ein brennbares Gas, Sauerstoff nährt Feuer, aber Wasser ist flüssig, hat Oberflächenspannung und macht Dinge nass. Ein einzelnes H₂O-Molekül ist nicht nass; die Eigenschaft zeigt sich erst im Zusammenspiel unzähliger Moleküle, die über Wasserstoffbrücken aneinander haften. Der Fehler liegt im Sprung von „nicht an einem einzelnen Teil ablesbar“ zu „Teile untersuchen bringt nichts“. Gerade die Kräfte zwischen den Molekülen erklären, warum Wasser Tropfen bildet und Oberflächen benetzt: Nässe widerspricht der Chemie nicht, sie baut auf ihr auf. Wer verstehen will, muss also die Teile und ihr Zusammenspiel untersuchen, nicht das eine statt des anderen.","coreRule":"⚡ Eine emergente Eigenschaft steckt in den Beziehungen der Teile, nicht in den Teilen selbst, und sie baut auf den Gesetzen der Teile auf, statt ihnen zu widersprechen.","beleg":"Werkstück A.22 (Einstiegsgeschichte, Das Wasser; Anti-Denkmuster: Konsistenz)","status":"entwurf","scenario":"","kurz":"Aus „Nässe lässt sich nicht an Wasserstoff, Sauerstoff oder einem einzelnen Molekül ablesen“ folgt nicht „Einzelteile zu untersuchen bringt nichts“. Nässe baut auf der Chemie der Moleküle auf, sie zeigt sich nur erst in ihrem Zusammenspiel.","prueffrage":"Woher stammt das heutige Wissen darüber, warum Wasser Tropfen bildet und Oberflächen benetzt?","rueckmeldung":[{"option":0,"text":"Dass Nässe erst im Zusammenspiel vieler Moleküle entsteht, stimmt, und gerade darauf stützt sich der Redner. Sein Fehler liegt im Sprung zu „Teile untersuchen bringt nichts“: Die Beobachtung zeigt nur, dass die Teile allein nicht reichen."},{"option":2,"text":"Der Redner verwechselt nichts, und „jede Flüssigkeit macht nass“ stimmt nicht einmal: Quecksilber benetzt Glas nicht. Vor allem geht das am eigentlichen Fehler vorbei, dem Sprung von der Beobachtung zu „Einzelteile untersuchen bringt nichts“."},{"option":3,"text":"Ein einzelnes H₂O-Molekül ist nicht nass; Nässe zeigt sich erst im Zusammenspiel sehr vieler Moleküle. Auch eine Computersimulation muss deshalb viele Moleküle und ihre Wechselwirkungen nachbilden, ein einzelnes allein genügt nicht."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Surface Tension and Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/surface-tension-and-water","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-041","clusterId":"A","werkstueckRef":"A.22","stufe":3,"question":"Du hörst in einer Diskussion diese Erklärung: „Wie die Methode wirkt? Das ist eine emergente Eigenschaft des Quantenfeldes.“ Was ist an dieser Antwort der entscheidende Schwachpunkt?","options":["Die Antwort benennt keinen Mechanismus: Es bleibt offen, welche Wechselwirkungen welcher Teile die behauptete Wirkung erzeugen sollen.","Die Antwort ist zu fachsprachlich gehalten; sobald sie in Alltagssprache formuliert wäre, wäre die Behauptung überprüfbar und damit belegt.","Die Antwort setzt voraus, dass Emergenz nur in lebenden Systemen vorkommt, während Felder und Teilchen nie neue Eigenschaften zeigen.","Die Antwort scheitert, weil sich emergente Eigenschaften grundsätzlich nicht erklären lassen und jede Erklärung deshalb unzulässig ist."],"correctIndex":0,"explanation":"Emergenz beschreibt nur, dass auf einer höheren Ebene Eigenschaften auftauchen, die einzelne Teile nicht zeigen. Sie erklärt nichts, solange offen bleibt, wie das geschieht. Ein Verkehrsforscher kann die Regeln nennen, nach denen aus dem Verhalten einzelner Fahrer ein Stau entsteht. Wer dagegen nur sagt „Das ist emergent“, ersetzt den Mechanismus durch ein Etikett und beendet die Diskussion, statt sie zu beginnen. Prüffragen: Welche Interaktionen zwischen welchen Komponenten erzeugen die Wirkung? Und widerspricht sie bekannten physikalischen Gesetzen? Echte Emergenz baut auf den Gesetzen der unteren Ebene auf und bricht sie nicht.","coreRule":"⚡ „Es ist emergent“ ist keine Erklärung, solange kein Mechanismus benannt wird.","quote":"Das ist eine emergente Eigenschaft des Quantenfeldes.","quoteLabel":"Beispielantwort:","beleg":"Werkstück A.22 (Anwendung: Pseudowissenschaftlicher Missbrauch; Der Kipppunkt; Aktivierungs-Frage 1)","status":"entwurf","scenario":"Eine Anbieterin von „Energieheilung“ wird gefragt, wie ihre Methode funktioniert. Sie antwortet: „Das ist eine emergente Eigenschaft des Quantenfeldes.“ Danach geht das Gespräch zu einem anderen Thema über.","kurz":"„Emergent“ besagt nur, dass auf höherer Ebene neue Eigenschaften auftreten, nicht wie. Ohne Angabe, welche Wechselwirkungen welcher Teile die Wirkung erzeugen, ersetzt das Etikett den Mechanismus und beendet die Diskussion.","prueffrage":"Was sagt die Anbieterin nach diesem Satz noch über ihre Methode, und was weiß man danach mehr als vorher?","rueckmeldung":[{"option":1,"text":"Fachwörter können Leere tatsächlich verdecken. Einfachere Sprache macht eine Behauptung aber noch nicht überprüfbar, geschweige denn belegt; dafür bräuchte es einen benannten Mechanismus, und genau der fehlt."},{"option":2,"text":"Emergenz ist nicht auf Lebewesen beschränkt, auch die Nässe von Wasser entsteht erst aus dem Zusammenspiel vieler Teilchen. Zudem setzt der Satz das gar nicht voraus: Er schreibt die Emergenz ja einem Quantenfeld zu."},{"option":3,"text":"Emergente Eigenschaften lassen sich oft gut erklären, etwa über die Regeln, nach denen einzelne Fahrer einen Stau erzeugen. Nicht das Erklären ist unzulässig, sondern das bloße Etikett „emergent“ ohne jede Erklärung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a2-042","clusterId":"A","werkstueckRef":"A.22","stufe":4,"question":"Ein Anbieter erklärt, sein „energetisiertes“ Wasser heile Beschwerden. Auf die Rückfrage nach dem Wirkmechanismus sagt er: „Das ist eine emergente Eigenschaft des Wassers, die man nicht auf einzelne Moleküle zurückführen kann.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Welche Wechselwirkungen zwischen welchen Bestandteilen sollen diese Eigenschaft erzeugen, und passt sie zu den bekannten Gesetzen der Physik?","Wie viele Kundinnen und Kunden haben das Wasser schon gekauft, und wie zufrieden sind diese damit?","Welche anerkannten Fachleute haben das Wort „emergent“ schon einmal in einem ähnlichen Zusammenhang verwendet?","Lässt sich die behauptete Wirkung durch eine genaue Untersuchung eines einzelnen Wassermoleküls vorhersagen?"],"correctIndex":0,"explanation":"Das Wort „emergent“ beschreibt nur, dass auf höherer Ebene etwas Neues entsteht; es erklärt nichts. Seriöse Forschung fragt deshalb nach den Interaktionen, die eine emergente Eigenschaft erzeugen. Nässe ist ein Beispiel: Sie entsteht aus dem Zusammenspiel unzähliger Wassermoleküle und ihrer Wasserstoffbrückenbindungen und widerspricht der Chemie nicht. Ein Verkehrsforscher kann die Regeln nennen, aus denen ein Stau entsteht. Wer „Emergenz“ ruft, aber keinen Mechanismus nennen kann oder ein Phänomen behauptet, das bekannten Gesetzen widerspricht, benutzt das Wort als Diskussionsende statt als Forschungsfrage. Die Rückfrage nach Mechanismus und Vereinbarkeit mit den Gesetzen darunter trennt beides. Kundenzahl und Zufriedenheit sagen nichts über den Mechanismus. Dass andere das Wort benutzen, beweist nichts. Und weil emergente Eigenschaften gerade nicht aus einer einzelnen Komponente ablesbar sind, wäre die Untersuchung eines einzelnen Moleküls der falsche Test.","coreRule":"⚡ „Emergent“ ist eine Beschreibung, keine Erklärung: Verlange den Mechanismus und prüfe, ob er den bekannten Gesetzen widerspricht.","beleg":"Werkstück A.22 (Red Flags; Anti-Denkmuster, Aktivierungs-Frage 2)","status":"entwurf","scenario":"","kurz":"„Emergent“ benennt nur, dass auf höherer Ebene etwas Neues entsteht, und erklärt noch nichts. Prüfen lässt sich die Behauptung, indem man nach den Wechselwirkungen fragt, die den Effekt erzeugen sollen, und danach, ob er zu den bekannten Gesetzen passt.","prueffrage":"Was genau müsste im Wasser anders sein, damit sich ein Unterschied zu gewöhnlichem Wasser nachweisen ließe?","rueckmeldung":[{"option":1,"text":"Viele zufriedene Kundinnen und Kunden wirken wie ein Indiz, sagen aber nur etwas über Beliebtheit aus. Ob und wodurch das Wasser wirkt, bleibt offen, denn Erwartung und Zufall können Zufriedenheit ebenso erklären."},{"option":2,"text":"Wenn Fachleute das Wort schon anderswo benutzt haben, klingt es seriös. Der Wortgebrauch anderer erklärt aber keinen Effekt dieses Wassers: Ein Wort wird nicht dadurch zum Mechanismus, dass es oft fällt."},{"option":3,"text":"Hier wird etwas Konkretes geprüft, aber auf der falschen Ebene. Emergente Eigenschaften wie Nässe entstehen erst aus dem Zusammenspiel vieler Moleküle und lassen sich an einem einzelnen nicht ablesen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-a2-043","clusterId":"A","werkstueckRef":"A.23","stufe":1,"question":"Eine Analystin sagt über diese Aktie: „Der Kurs steigt seit Wochen gleichmäßig, jede Woche um etwa zwei Prozent. Das System ist stabil, also wird das noch lange so weitergehen.“ Welche Frage prüft am besten, ob dieses System kurz vor einem Umschlag stehen könnte?","options":["Wie stark schwankt der Kurs im Vergleich zu den Wochen davor, und wie schnell erholt er sich von kleinen Rückschlägen?","Wie hoch war der durchschnittliche Wochengewinn im vergangenen Jahr, und liegt er über dem langjährigen Marktmittel?","Wie viele Mitglieder hat das Forum, und wie viele davon haben in den letzten Monaten neu gekauft?","Wie oft wurde der Kurs in der Vergangenheit schon als überbewertet bezeichnet, und was geschah danach?"],"correctIndex":0,"explanation":"Ein stetiger Anstieg beweist keine Stabilität: Systeme verändern sich oft lange gleichmäßig und kippen dann in einem Sprung, wie ein Glas, das zentimeterweise über den Tisch geschoben wird, bis die Kante erreicht ist. Die Schilderung zeigt typische Zutaten: Ein verstärkender Motor läuft (die Angst, etwas zu verpassen, treibt neue Käufer an), die Bremsen versagen (Gegenstimmen werden ausgegrenzt) und die Spannung wächst (Kredite machen das System anfällig). Wie nah die Kante ist, zeigt sich aber am besten am Verhalten des Systems selbst: Nahe an einem Umschlag erholt es sich oft langsamer von kleinen Störungen, und die Schwankungen nehmen zu. Die anderen Fragen betreffen Durchschnittswerte, die Zahl der Käufer oder alte Prognosen; sie zeigen allenfalls, dass Druck im System steckt, kaum aber, wie nah es am Kippen ist. Auch Schwankung und Erholung verraten nicht, wann das System kippt, und sie können Fehlalarm geben.","coreRule":"⚡ Stetig heißt nicht stabil: Frag nach Motoren, Bremsen und Spannung, und beobachte, wie schnell sich das System von kleinen Störungen erholt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikatoren 1 bis 3)","status":"entwurf","scenario":"Im Chat eines Anlegerforums zu einer bestimmten Aktie wächst die Zahl der Beiträge, in denen Leute schreiben, sie wollten „auf keinen Fall den Zug verpassen“. Kritische Stimmen werden dort ausgelacht oder gesperrt. Viele Mitglieder haben Kredite aufgenommen, um zu kaufen.","quote":"","quoteLabel":"","kurz":"Ein gleichmäßiger Anstieg beweist keine Stabilität: Systeme verändern sich oft lange gleichmäßig und kippen dann plötzlich. Hinweise gibt das Verhalten des Systems selbst, denn nahe am Umschlag nehmen die Schwankungen oft zu und Rückschläge klingen langsamer ab.","prueffrage":"Was weiß die Analystin über den Kursverlauf, außer dass er im Durchschnitt zwei Prozent pro Woche steigt?","rueckmeldung":[{"option":1,"text":"Ein Vergleich mit dem Vorjahr und dem Marktmittel ordnet den Anstieg ein. Er sagt aber nur, wie hoch die Rendite ist, nicht, wie nah das System an einem Schwellenwert steht."},{"option":2,"text":"Wie viele mitmachen und neu kaufen, zeigt, wie stark der Sog ist und dass Druck im System steckt. Wie nah es am Kippen ist, verrät das kaum; darüber sagt das Verhalten des Kurses selbst mehr."},{"option":3,"text":"Wie oft der Kurs schon als überbewertet galt, liefert Anschauung, sagt aber wenig über den heutigen Zustand, denn solche Urteile können lange danebenliegen. Wie nah das System am Kippen ist, zeigt eher das Verhalten des Kurses selbst."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-a2-044","clusterId":"A","werkstueckRef":"A.23","stufe":2,"question":"Was übersieht die Nutzerin, wenn man den Wandel der Gruppe als instabiler werdendes System betrachtet?","scenario":"In einer Nachbarschaftsgruppe fielen früher Gerüchte schnell in sich zusammen, weil ein paar besonnene Leute sie einordneten. Die sind inzwischen ausgetreten. Seitdem schaukelt sich der Ton bei jedem Gerücht rasch hoch. Eine Nutzerin sagt: „Das Problem sind nur die Gerüchte selbst. Wenn die nicht wären, wäre alles ruhig.“","options":["Dass auch die Gerüchte selbst nur dann zum Problem werden, wenn sich die Mitglieder ohnehin schon über sie aufregen wollen.","Dass die Einordnung weggefallen ist, die solche Aufschaukelungen früher gedämpft hat.","Dass sich Gerüchte in Gruppen mit sehr vielen Mitgliedern grundsätzlich schneller verbreiten als in kleinen Gruppen.","Dass die Gerüchte vermutlich von Anfang an absichtlich gestreut wurden, um die Gruppe zu spalten."],"correctIndex":1,"explanation":"Gerüchte gab es in der Gruppe schon vorher. Geändert hat sich vor allem, dass eine ausgleichende Schleife weggefallen ist: Die besonnene Einordnung wirkte als Bremse, die hitzige Reaktionen abgefangen hat. Systeme kippen oft dann, wenn solche Bremsen überlastet, ausgehebelt oder entfernt werden, etwa wenn Normen, Gesetze oder Peer Review wegfallen. Wer nur auf den Auslöser schaut, sieht nur den Funken und übersieht die fehlende Bremse; deshalb lohnt es sich, nicht nur nach den Antrieben zu fragen, sondern auch nach den Bremsen. Die Alternativen verschieben die Ursache nur: auf die Absicht der Mitglieder, auf die Gruppengröße oder auf eine Verschwörung. Keine davon erklärt, warum sich der Ton gerade nach dem Weggang der Besonnenen verändert hat.","coreRule":"⚡ Frag nicht nur, was antreibt, sondern auch, welche Bremse fehlt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikator 2)","status":"entwurf","kurz":"Gerüchte gab es auch früher, doch besonnene Leute haben sie eingeordnet und so abgefangen; mit deren Austritt fehlt diese Bremse. Wer nur auf die Gerüchte als Auslöser schaut, übersieht, dass die Dämpfung weggefallen ist.","prueffrage":"Gab es in der Gruppe auch früher schon Gerüchte, und wie lange hielten sie sich damals?","rueckmeldung":[{"option":0,"text":"Dass die Gerüchte allein nicht der Grund sind, stimmt. Für einen Aufregungswillen der Mitglieder gibt es aber keinen Anhalt, und er erklärt nicht, warum sich der Ton erst nach dem Austritt der Besonnenen veränderte."},{"option":2,"text":"Von der Größe der Gruppe ist nirgends die Rede, eher ist sie durch die Austritte kleiner geworden. Und selbst wenn Größe die Verbreitung beschleunigt: Sie erklärt nicht, warum der Ton gerade nach dem Weggang der Besonnenen kippte."},{"option":3,"text":"Eine gezielte Streuung klingt nach einer eleganten Erklärung für das Hochschaukeln, ist aber durch nichts belegt. Gerüchte gab es schon vorher, und der Wandel setzt erst mit dem Austritt der Besonnenen ein."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-a2-045","clusterId":"A","werkstueckRef":"A.23","stufe":3,"question":"Eine Analystin hat gelernt, nach verstärkenden Rückkopplungen, versagenden Bremsen und aufgestauter Spannung zu suchen. Sie sieht inzwischen in jedem Kursausschlag, jedem Streit im Team und jedem Ausreißer in einer Statistik den Beginn eines Zusammenbruchs. Was ist an ihrem Vorgehen das Problem?","options":["Sie deutet gewöhnliche Schwankungen als Vorboten einer Katastrophe und macht ihre Warnungen dadurch durch keine Beobachtung mehr widerlegbar.","Sie fragt zu viele Dinge gleichzeitig und müsste sich auf einen einzigen Indikator beschränken, um ein klares Ergebnis zu erhalten.","Sie wendet das Raster auf Systeme an, die schon gekippt sind, und sucht damit rückblickend nach Ursachen statt nach künftigen Entwicklungen.","Sie gewichtet die aufgestaute Spannung zu stark und beachtet die Bremsen zu wenig, sodass ihre Einschätzung einseitig ausfällt."],"correctIndex":0,"explanation":"Ein Denkwerkzeug wird unbrauchbar, wenn es überall anschlägt. Wer harmlose Schwankungen als Beweis für den nahenden Zusammenbruch liest, erkennt Muster im Rauschen (Apophenie). Ihr Satz „Das zeigt nur, wie knapp es war“ macht die Behauptung zusätzlich unwiderlegbar: Tritt der Kollaps ein, hatte sie recht, tritt er nicht ein, war es eben knapp. Eine Behauptung, die durch kein Ergebnis widerlegt werden kann, sagt nichts mehr aus. Dazu kommt: Auch seriöse Frühwarnsignale zeigen nur, dass ein System näher an die Kante rückt, nicht wann es kippt, und sie schlagen mitunter falschen Alarm. Brauchbar ist das Raster deshalb zur Beschreibung der Dynamik hinter einer Entwicklung (Motoren, Bremsen, Spannung, möglicher Auslöser), nicht als Prophezeiung.","coreRule":"⚡ Ein Prüfraster zeigt Architektur, keine Prophezeiung: Wer überall Kipppunkte sieht und jedes Ausbleiben als „knapp“ umdeutet, sieht Muster im Rauschen.","beleg":"Werkstück A.23 (Der Kipppunkt (Von der Nützlichkeit zur Gefahr); Red Flags: Langsameres Zurückfedern); Fn. ga-fruehwarnung (Scheffer u. a. 2009, Nature 461, S. 53–59) und Fn. ga-fruehsignale (Scheffer u. a. 2009, S. 54–58; Dakos 2011, S. 17–32)","status":"entwurf","scenario":"Eine Analystin nutzt ein Prüfraster für Kipppunkte. Sie fragt: Wo verstärkt sich etwas selbst? Welche Bremsen versagen? Wie viel Spannung hat sich aufgestaut? Seit sie damit arbeitet, warnt sie fast wöchentlich vor einem bevorstehenden Kollaps, ob bei Aktienkursen, Teamstimmung oder Kundenzahlen. Bisher ist keine ihrer Warnungen eingetreten, aber sie sagt: „Das zeigt nur, wie knapp es jedes Mal war.“","kurz":"Wer gewöhnliche Schwankungen als Vorboten liest, sieht Muster im Rauschen. Weil „wie knapp es jedes Mal war“ jeden Ausgang erklärt, kann zudem keine Beobachtung ihre Warnung widerlegen, und eine Behauptung, die nie falsch sein kann, sagt nichts mehr aus.","prueffrage":"Wie viele ihrer Warnungen sind bisher eingetreten, und wie erklärt die Analystin die übrigen?","rueckmeldung":[{"option":1,"text":"Mehrere Fragen zusammen beschreiben eine Dynamik meist besser als ein einzelner Indikator, der Hauptfehler liegt woanders. Die Warnungen bleiben auch mit nur einem Indikator unwiderlegbar, solange „knapp“ jeden Ausgang erklärt."},{"option":2,"text":"Ein Raster lässt sich im Nachhinein auf gekippte Systeme anwenden, hier geht es aber um Warnungen vor bevorstehenden Kollapsen, die bisher nie eintraten. Das Problem liegt also im Umgang mit dem Raster, nicht in einer Blickrichtung nach hinten."},{"option":3,"text":"Ausgewogen zu gewichten ist sinnvoll, doch für eine Schieflage gibt es keinen Hinweis: Sie fragt nach Verstärkung, Bremsen und Spannung. Bessere Gewichtung änderte nichts daran, dass „wie knapp es war“ jede Warnung gegen Widerlegung abschirmt."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-046","clusterId":"A","werkstueckRef":"A.23","stufe":4,"question":"Ein Team beobachtet über Monate ein Ökosystem. Die Messwerte zeigen: Nach kleinen Störungen erholt es sich immer langsamer, die Schwankungen werden größer, und jeder Zustand gleicht stärker dem vorigen. Eine Kollegin sagt: „Dann kippt das System in den nächsten Wochen, das ist jetzt sicher.“ Was ist die beste Einschätzung?","options":["Die Signale sprechen dafür, dass die Kante näher rückt, doch den Zeitpunkt des Kippens und ob es überhaupt kippt, sagen sie nicht verlässlich voraus.","Die Signale zeigen an, dass sich das System festigt, denn größere Schwankungen belegen, dass es Störungen immer besser abfedert.","Die Signale sind nur aussagekräftig, wenn sie in mehreren Fachgebieten gleichzeitig auftreten, dann lässt sich der Zeitpunkt des Kippens genau berechnen.","Die Signale gelten nur für Klimadaten, deshalb lässt sich aus ihnen für Tierbestände oder andere Systeme nichts ableiten."],"correctIndex":0,"explanation":"Wenn sich ein System nahe einer Schwelle langsamer von kleinen Störungen erholt, stärker schwankt und jeder Zustand dem vorigen ähnlicher wird, rückt die Kante näher. Das ist ein allgemeines Muster, das in Modellen, in Klimadaten der Erdgeschichte, bei befischten Beständen und vor epileptischen Anfällen gefunden wurde. Es sagt aber nur etwas über die Nähe, nicht über den Zeitpunkt: Solche Signale schlagen mitunter falschen Alarm oder bleiben vor einem echten Umbruch stumm. Die Kollegin schließt also zu viel aus einem Warnsignal. Ein Anlass, genauer hinzusehen und Vorsorge zu treffen, ist es, aber keine Prognose mit Datum.","coreRule":"⚡ Frühwarnsignale zeigen die Nähe der Kante, nicht den Zeitpunkt des Sturzes.","beleg":"Werkstück A.23 (Red Flags: Langsameres Zurückfedern); Fn. ga-fruehsignale (Scheffer u. a. 2009, Nature 461(7260), S. 53–59, nach Dakos 2011, S. 21, 24, 27–29, 31)","status":"entwurf","scenario":"","kurz":"Langsamere Erholung, größere Schwankungen und wachsende Ähnlichkeit aufeinanderfolgender Zustände zeigen, dass die Kante näher rückt, nicht aber wann es kippt. Die Kollegin macht aus einem Warnsignal eine Prognose mit Datum; Fehlalarme und ausbleibende Signale gibt es.","prueffrage":"Welche drei Veränderungen hat das Team gemessen, und wie würde sich ein stabiles System nach kleinen Störungen verhalten?","rueckmeldung":[{"option":1,"text":"Dass ein stabiles System Störungen abfedert, stimmt grundsätzlich. Beobachtet wird hier aber das Gegenteil: Langsamere Erholung und größere Schwankungen sprechen dafür, dass sich das System einer Schwelle nähert."},{"option":2,"text":"Mehrere Fachgebiete klingen nach mehr Gewissheit. Das Muster gilt aber schon für ein einzelnes System, und selbst dann sagt es nur etwas über die Nähe der Kante. Einen genau berechenbaren Zeitpunkt liefert es nirgends."},{"option":3,"text":"Klimadaten gehören tatsächlich zu den Fundstellen, doch das Muster wurde auch bei befischten Beständen und vor epileptischen Anfällen gefunden. Es ist also nicht auf ein Gebiet beschränkt; begrenzt ist es darin, dass es keinen Zeitpunkt nennt."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dakos, V. u. a. (2008): Slowing down as an early warning signal for abrupt climate change. PNAS 105(38), 14308–14312","oeffentlich":true,"doi":"10.1073/pnas.0802430105","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"}],"thema":"Natur und Klima"},{"id":"qx-a2-047","clusterId":"A","werkstueckRef":"A.24","stufe":1,"question":"Eine Forscherin sieht sich ihre Messdaten erst an und stellt dann fest, dass sich in einer Untergruppe ein „signifikanter“ Effekt zeigt. In ihrer Veröffentlichung schreibt sie, genau diesen Effekt habe sie von Anfang an erwartet. Welche Maßnahme hätte dieses Vorgehen am wirksamsten verhindert?","options":["Hypothese, Stichprobengröße und Auswertungsplan vor der Datenerhebung mit Zeitstempel hinterlegen; spätere Funde als explorativ kennzeichnen.","Nur Studien veröffentlichen, deren Ergebnis die Hypothese eindeutig bestätigt, damit unklare Befunde gar nicht erst im Umlauf sind.","Hypothese und Auswertungsplan erst nach einer gründlichen Durchsicht der Daten festlegen, damit sie möglichst gut zu den Daten passen.","Nach dem Erscheinen der Studie zählen, wie viele vergleichbare Studien nie veröffentlicht wurden, und das im Bericht vermerken."],"correctIndex":0,"explanation":"Wer erst die Daten ansieht und dann die Hypothese formuliert (HARKing), findet bei genügend Variablen und Untergruppen fast immer etwas: Es ist, als würde man erst schießen und dann die Zielscheibe malen. Dagegen hilft nur, die Wette vorher zu versiegeln. Wenn Hypothese und Plan vor den Daten feststehen und belegbar sind, lässt sich nachprüfen, ob das Ergebnis erwartet oder nachträglich zurechtgelegt wurde. Alles, was später zusätzlich auftaucht, bleibt erlaubt, zählt aber als Idee für die nächste Studie und nicht als Beweis. Die anderen Wege setzen an der falschen Stelle an: Nur Bestätigendes zu drucken verstärkt die Verzerrung, Pläne nach Dateneinsicht sind genau das Problem, und das Zählen unveröffentlichter Studien betrifft den Publikationsbias und verhindert nicht, dass die Hypothese nachträglich zurechtgelegt wird. Eine Auswertung großer US-Herz-Kreislauf-Studien stützt das: Vor 2000, ohne Pflicht zur vorherigen Festlegung der Zielgröße, meldeten 17 von 30 Studien (57 Prozent) einen Nutzen, danach 2 von 25 (8 Prozent). Die Autoren halten für möglich, dass die Registrierung dazu beitrug.","coreRule":"⚡ Erst die Wette versiegeln, dann die Karten aufdecken: Hypothese vor den Daten.","quote":"Alles, was danach zusätzlich gefunden wird, ist erlaubt -- aber als *explorativ* zu kennzeichnen, als Idee für die nächste Studie, nicht als Beweis in dieser.","quoteLabel":"Merksatz:","beleg":"Werkstück A.24 (Werkzeug 2: Präregistrierung); Fn. ga-praeregistrierung (Kaplan/Irvin 2015, PLOS ONE 10(8), e0132382; Kerr 1998)","status":"entwurf","scenario":"Eine Studie wertet viele Variablen und Untergruppen aus. Bei genügend Auswertungswegen liefert der Zufall fast immer irgendwo ein „signifikantes“ Muster. Im Bericht steht später, die Hypothese sei von Anfang an klar gewesen.","kurz":"Nur eine vorab festgelegte, belegbare Hypothese mit Plan lässt sich später mit dem Ergebnis abgleichen. Wer erst die Daten sieht und dann „erwartet“, was auffiel, malt die Zielscheibe um den Einschlag. Spätere Funde bleiben als Ideen erlaubt.","prueffrage":"In wie vielen Untergruppen hat die Forscherin nach einem Effekt gesucht, und in wie vielen ist sie fündig geworden?","rueckmeldung":[{"option":1,"text":"Unklare Befunde auszusortieren wirkt aufgeräumt. Damit entsteht aber ein verzerrtes Bild, und die nachträglich zurechtgelegte Hypothese bleibt unberührt: Wer nur Bestätigendes druckt, verstärkt das Problem."},{"option":2,"text":"Ein Plan, der zu den Daten passt, klingt nach sorgfältiger Arbeit. Er passt aber nur, weil er nach der Dateneinsicht entstand. Genau dieses Zurechtlegen ist das Problem, das hier vermieden werden soll."},{"option":3,"text":"Unveröffentlichte Studien zu zählen macht tatsächlich etwas sichtbar, nämlich den Publikationsbias. Das ist ein anderes Problem. Es kommt erst nach dem Erscheinen und verhindert nicht, dass eine Hypothese nachträglich zurechtgelegt wird."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A.; Ebersole, C. R.; DeHaven, A. C.; Mellor, D. T. (2018): The preregistration revolution. PNAS 115(11), 2600–2606","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kaplan, R. M.; Irvin, V. L. (2015): Likelihood of Null Effects of Large NHLBI Clinical Trials Has Increased over Time. PLOS ONE 10(8), e0132382","oeffentlich":true,"doi":"10.1371/journal.pone.0132382","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kerr, N. L. (1998): HARKing: Hypothesizing After the Results are Known. Personality and Social Psychology Review 2(3), 196–217","oeffentlich":false}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-048","clusterId":"A","werkstueckRef":"A.24","stufe":2,"question":"Eine Zeitung titelt: „Mittel wirkt nicht: Ergebnis nicht signifikant (p = 0,06).“ Welche Überlegung ist hier am sinnvollsten?","options":["Ein p-Wert über 0,05 beweist, dass das Mittel wirkungslos ist, und damit ist die Frage geklärt.","Ein p-Wert über 0,05 zeigt, dass die Messung fehlerhaft war, und die Studie muss als ungültig gelten.","Die Schwelle von 0,05 ist eine Konvention, und eine Wirkung bleibt mit den Daten vereinbar, solange das Intervall sie nicht ausschließt.","Bei p = 0,06 war allein der Zufall am Werk, während bei p = 0,04 sicher keine Zufallsschwankung mehr im Spiel gewesen wäre."],"correctIndex":2,"explanation":"„Nicht signifikant“ heißt nicht „kein Effekt“. Es heißt nur, dass die Daten die Annahme „gar keine Wirkung“ nicht deutlich genug widerlegen. Die Schwelle von 5 Prozent ist eine Konvention, kein Naturgesetz: Ein Ergebnis mit p = 0,06 und eines mit p = 0,04 unterscheiden sich kaum, werden aber als „wirkt nicht“ und „wirkt“ verkauft. Auch ein signifikantes Ergebnis schließt den Zufall nicht aus, und ein nicht signifikantes beweist keine Wirkungslosigkeit. Die American Statistical Association warnte 2016 vor genau diesem Gebrauch des p-Werts, und 2019 forderten über 800 Forschende in Nature, „statistisch signifikant“ nicht länger als Ja-Nein-Urteil zu verwenden. Sinnvoll ist es, das Konfidenzintervall zu lesen: Es zeigt, welche Effektgrößen mit den Daten vereinbar sind, und damit auch, ob eine bedeutsame Wirkung noch möglich ist.","coreRule":"⚡ Lies das Intervall, nicht nur das Etikett „signifikant“ oder „nicht signifikant“.","beleg":"Werkstück A.24 (Werkzeug 3: Konfidenzintervall); Fn. ga-signifikanz (Wasserstein/Lazar 2016, The American Statistician 70(2), S. 131–132; Amrhein u. a. 2019, Nature 567, S. 305–307)","status":"entwurf","scenario":"In der Meldung steht nur der p-Wert. Zur Größe des Effekts oder zu einem Konfidenzintervall wird nichts gesagt.","kurz":"Mit p = 0,06 sind die Daten nur nicht deutlich genug gegen „keine Wirkung“, das beweist aber keine Wirkungslosigkeit. Die Grenze von 0,05 ist Konvention; das Konfidenzintervall zeigt, welche Effekte noch möglich sind.","prueffrage":"Würde die Schlagzeile umgekehrt lauten, wenn p = 0,04 herausgekommen wäre, und wie groß wäre dieser Unterschied in den Daten?","rueckmeldung":[{"option":0,"text":"Ein p-Wert über 0,05 klingt nach einem klaren Urteil. Er sagt aber nur, dass die Daten die Annahme „gar keine Wirkung“ nicht deutlich genug widerlegen. Wirkungslosigkeit lässt sich damit nicht beweisen, die Frage bleibt offen."},{"option":1,"text":"Über der Schwelle zu liegen wirkt wie ein Warnsignal, sagt aber nichts über die Qualität der Messung. Der p-Wert beschreibt, wie gut die Daten zur Annahme „kein Effekt“ passen, nicht ob die Studie gültig ist."},{"option":3,"text":"Die Schwelle 0,05 wirkt wie eine scharfe Grenze zwischen Zufall und Wirkung. Doch 0,06 und 0,04 unterscheiden sich kaum: Weder ist bei 0,06 „allein der Zufall“ am Werk, noch ist er bei 0,04 ausgeschlossen."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung, 7. März 2016)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wasserstein, R. L.; Lazar, N. A. (2016): The ASA Statement on p-Values: Context, Process, and Purpose. The American Statistician 70(2), 129–133","oeffentlich":false,"doi":"10.1080/00031305.2016.1154108"},{"typ":"literatur","kurz":"Amrhein, V.; Greenland, S.; McShane, B. (2019): Scientists rise up against statistical significance. Nature 567, 305–307","oeffentlich":false,"doi":"10.1038/d41586-019-00857-9"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-a2-049","clusterId":"A","werkstueckRef":"A.24","stufe":3,"question":"Was folgt aus diesen Angaben?","options":["Der Effekt ist groß, weil bei so vielen Teilnehmern ein Zufallsbefund praktisch ausgeschlossen ist.","Der Effekt ist nicht nachgewiesen, weil ein d unter 0,2 stets bedeutet, dass die Daten nichts hergeben.","Der Effekt ist statistisch nachweisbar, aber praktisch winzig, weil Signifikanz nichts über die Größe eines Effekts aussagt.","Der Effekt ist mittelstark, weil bei so großer Stichprobe schon d = 0,02 als mittlerer Effekt zählt."],"correctIndex":2,"explanation":"Mit einer hinreichend großen Stichprobe wird jeder noch so winzige Unterschied signifikant. Signifikanz sagt nur, dass die Daten schlecht zur Annahme „gar kein Effekt“ passen, nicht, wie groß der Effekt ist. Die gemeldeten Werte (d = 0,001 bis 0,02) liegen deutlich unter der Konvention für einen kleinen Effekt (ab d = 0,2) und sind im Alltag eines einzelnen Nutzers unsichtbar. Die Schlagzeile verwechselt „nachweisbar“ mit „bedeutend“. Die prüfende Frage lautet: Wie groß ist der Effekt in einer Einheit, die ich mir vorstellen kann?","coreRule":"⚡ Signifikanz beantwortet „Gibt es etwas?“, die Effektstärke „Wie viel?“.","beleg":"Werkstück A.24 (Werkzeug 4: Effektstärke); Fn. ga-effektstaerke (Kramer u. a. 2014, PNAS 111(24), S. 8788–8790; Cohen 1988)","status":"entwurf","scenario":"Eine Schlagzeile lautet: „Studie beweist: Gefühle stecken über soziale Netzwerke an.“ Im Studienbericht steht: Bei 689.003 Teilnehmern „steckte“ die Stimmung durch manipulierte Nachrichtenfeeds messbar an; das Ergebnis ist hochsignifikant (p-Wert extrem klein), die Effektstärke d liegt zwischen 0,001 und 0,02. Als Faustregel gilt: Ab d = 0,2 spricht man von einem kleinen, ab 0,5 von einem mittleren und ab 0,8 von einem großen Effekt.","kurz":"Hochsignifikant heißt nur, dass die Daten schlecht zu „gar kein Effekt“ passen, nicht, dass der Effekt groß wäre. Bei so vielen Teilnehmern wird schon ein winziger Unterschied signifikant, und d = 0,001 bis 0,02 liegt weit unter einem kleinen Effekt.","prueffrage":"Wie viel Stimmungsänderung steckt in diesem Wert, wenn du ihn in etwas Greifbares umrechnest?","rueckmeldung":[{"option":0,"text":"Bei so kleinem p-Wert passen die Daten tatsächlich sehr schlecht zu „gar kein Effekt“. Das spricht dafür, dass es einen Effekt gibt, sagt aber nichts über seine Größe: Mit d bis 0,02 liegt er weit unter einem kleinen Effekt."},{"option":1,"text":"Mit d = 0,001 bis 0,02 liegt der Effekt tatsächlich unter der Grenze für „klein“. Statistisch nachweisbar ist er trotzdem: Hochsignifikant heißt, dass die Daten schlecht zu „gar kein Effekt“ passen. Die Faustregel misst Größe, nicht Nachweisbarkeit."},{"option":3,"text":"Eine große Stichprobe macht kleine Unterschiede nachweisbar, verschiebt aber nicht die Einordnung der Größe. Ein mittlerer Effekt beginnt bei d = 0,5, und 0,02 liegt weit darunter."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kramer, A. D. I.; Guillory, J. E.; Hancock, J. T. (2014): Experimental evidence of massive-scale emotional contagion through social networks. PNAS 111(24), 8788–8790","oeffentlich":true,"doi":"10.1073/pnas.1320040111","abruf":"2026-10-12"},{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Cohen, J. (1988): Statistical Power Analysis for the Behavioral Sciences. 2. Aufl. Hillsdale: Erlbaum","oeffentlich":false}],"thema":"Netz und Medien"},{"id":"qx-a2-050","clusterId":"A","werkstueckRef":"A.24","stufe":4,"question":"Welche Frage prüft diesen Schluss am besten?","options":["Wie sieht das Verhältnis aus, wenn man Geimpfte und Ungeimpfte innerhalb derselben Altersgruppe vergleicht?","Wie viele Menschen in diesem Land sind insgesamt geimpft worden, unabhängig von ihrem Alter?","Wie viele Zeitungen haben die Meldung ebenfalls übernommen und mit eigenen Zahlen bestätigt?","Wie lange liegen die Schwerkranken durchschnittlich im Krankenhaus, bevor sie entlassen werden?"],"correctIndex":0,"explanation":"Die Gesamtzahl vermischt Gruppen, die sich im Risiko stark unterscheiden. Sind die Gefährdetsten zugleich fast alle geimpft, stellen Geimpfte einen großen Teil der Schwerkranken, selbst wenn die Impfung das Risiko in jeder Altersgruppe deutlich senkt. Ein solcher Zusammenhang, der in der Gesamtheit anders aussieht als in den Teilgruppen, heißt Simpson-Paradox. Ein berühmtes Beispiel: Berkeley 1973 ließ 44 Prozent der männlichen, aber nur 35 Prozent der weiblichen Bewerber zu. Nach Fachbereichen aufgeschlüsselt zeigte sich kein Nachteil für Frauen, weil sie sich häufiger in Fächern mit niedrigen Zulassungsquoten beworben hatten. Der Vergleich innerhalb gleicher Gruppen entscheidet also, was die Zahlen aussagen. Vorsicht in der Gegenrichtung: Nicht jede Aufteilung ist die richtige, und welche gilt, verraten die Zahlen allein nicht.","coreRule":"⚡ Teile die Gruppen auf, aber frag, welche Aufteilung der Zusammenhang wirklich verlangt.","beleg":"Werkstück A.24 (Werkzeug 5: Das Simpson-Paradox); Fn. ga-simpson (Bickel/Hammel/O'Connell 1975, Science 187(4175), S. 398–404; Morris 2021; Pearl 2014, The American Statistician 68(1), S. 8–13)","status":"entwurf","scenario":"In einem Land mit hoher Impfquote meldet eine Zeitung: „Mehr als die Hälfte der Schwerkranken im Krankenhaus ist geimpft. Die Impfung schützt also kaum.“ Bekannt ist außerdem: Die Ältesten sind fast vollständig geimpft und zugleich am stärksten gefährdet, schwer zu erkranken.","kurz":"Entscheidend ist der Vergleich innerhalb gleicher Altersgruppen. Die Gesamtzahl mischt Gruppen mit sehr unterschiedlichem Risiko: Sind fast alle Gefährdeten geimpft, stellen Geimpfte viele Schwerkranke, auch wenn die Impfung in jeder Altersgruppe das Risiko deutlich senkt.","prueffrage":"Unterscheiden sich die Geimpften und die Ungeimpften im Land außer durch die Impfung noch in etwas, das ihr Risiko für eine schwere Erkrankung beeinflusst?","rueckmeldung":[{"option":1,"text":"Die Gesamtzahl der Geimpften braucht man für Anteile, sie klärt aber nicht, ob die Gruppen vergleichbar sind. Dass die Quote hoch ist, steht schon fest. Offen bleibt, wie oft Geimpfte und Ungeimpfte gleichen Alters schwer erkranken."},{"option":2,"text":"Weitere Zeitungen mit denselben oder eigenen Zahlen bestätigen höchstens, dass die Zahlen stimmen. Ob der Schluss daraus trägt, klären sie nicht, solange in der Gesamtzahl Altersgruppen mit sehr verschiedenem Risiko vermischt sind."},{"option":3,"text":"Die Dauer des Krankenhausaufenthalts misst etwas anderes als die Schutzwirkung der Impfung. Sie sagt nichts darüber, ob Geimpfte und Ungeimpfte mit gleichem Risiko verglichen werden, und prüft den Schluss deshalb nicht."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Morris, J. (2021): Israeli data: How can efficacy vs. severe disease be strong when 60% of hospitalized are vaccinated? Covid Data Science","oeffentlich":true,"url":"https://www.covid-datascience.com/post/israeli-data-how-can-efficacy-vs-severe-disease-be-strong-when-60-of-hospitalized-are-vaccinated","abruf":"2026-10-12"},{"typ":"url","kurz":"Pearl, J. (2013): Understanding Simpson's Paradox. UCLA Technical Report R-414 (Vorfassung zu The American Statistician 68(1), 2014)","oeffentlich":true,"url":"https://ftp.cs.ucla.edu/pub/stat_ser/r414.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bickel, P. J.; Hammel, E. A.; O'Connell, J. W. (1975): Sex Bias in Graduate Admissions: Data from Berkeley. Science 187(4175), 398–404","oeffentlich":false}],"thema":"Gesundheit"}]`);export{t as n,n as t};